// The dev inspector PANEL — Ctrl+Shift+D (DX plan I3).
//
// A VIEW over the snapshot, and nothing else. It is handed `() => OsyProbe` — the same builder `__osy.dump()` calls —
// so the human view and the machine view cannot disagree: a field the panel shows is a field `dump()` returns, and a
// new tab is a new renderer over data that already exists. There is deliberately no second data path.
//
// Plain DOM, no framework (this client has none) and no external CSS: every style is inline so the panel cannot be
// restyled by — or restyle — the app it is inspecting. Dev-host only; a deployed app never constructs it.

import type { ComponentProbe, ControlProbe, OsyProbe } from './probe.js';

type TabId = 'components' | 'controls' | 'net' | 'data' | 'routes' | 'logs';

const C = {
  bg: 'rgba(17,19,24,0.97)',
  bar: '#0e1014',
  edge: '#2a2f3a',
  text: '#e8eaed',
  dim: '#9aa2b1',
  faint: '#6b7383',
  accent: '#5b9dff',
  good: '#3ecf8e',
  warn: '#f5a623',
  bad: '#ff6b6b',
  row: 'rgba(255,255,255,0.03)',
} as const;
const MONO = "'SF Mono','Fira Code',Menlo,Consolas,monospace";

/** Render a value compactly: short scalars inline, big structures truncated. A panel that prints a 4000-row array is
 *  as useless as one that prints nothing. */
function short(v: unknown, max = 120): string {
  if (v === null) return 'null';
  if (v === undefined) return 'undefined';
  if (typeof v === 'string') return v.length > max ? `"${v.slice(0, max)}…"` : `"${v}"`;
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (Array.isArray(v)) return `[${v.length}]`;
  try {
    const j = JSON.stringify(v);
    return j.length > max ? `${j.slice(0, max)}…` : j;
  } catch { return String(v); }
}

const el = (doc: Document, tag: string, style: string, text?: string): HTMLElement => {
  const e = doc.createElement(tag);
  e.setAttribute('style', style);
  if (text !== undefined) e.textContent = text;
  return e;
};

/** A `key  value` row with an optional trailing badge. */
function kv(doc: Document, key: string, value: string, badge?: { text: string; color: string }): HTMLElement {
  const row = el(doc, 'div', `display:flex;gap:8px;align-items:baseline;padding:2px 0;`);
  row.appendChild(el(doc, 'span', `color:${C.dim};min-width:150px;flex:0 0 auto;`, key));
  row.appendChild(el(doc, 'span', `color:${C.text};word-break:break-all;flex:1 1 auto;`, value));
  if (badge) row.appendChild(el(doc, 'span', `color:${badge.color};flex:0 0 auto;font-size:11px;`, badge.text));
  return row;
}

function section(doc: Document, title: string): HTMLElement {
  return el(doc, 'div', `color:${C.accent};font-weight:600;margin:10px 0 4px;font-size:11px;letter-spacing:.06em;text-transform:uppercase;`, title);
}

// ── tabs ──────────────────────────────────────────────────────────────────────────────────────────────

function renderComponent(doc: Document, node: ComponentProbe, depth = 0): HTMLElement {
  const box = el(doc, 'div', `margin-left:${depth ? 14 : 0}px;border-left:${depth ? `1px solid ${C.edge}` : 'none'};padding-left:${depth ? 10 : 0}px;margin-top:8px;`);

  const head = el(doc, 'div', 'display:flex;gap:8px;align-items:baseline;');
  head.appendChild(el(doc, 'span', `color:${C.text};font-weight:600;`, node.name));
  head.appendChild(el(doc, 'span', `color:${C.faint};font-size:11px;`, node.path));
  if (node.isDirty) head.appendChild(el(doc, 'span', `color:${C.warn};font-size:11px;`, 'dirty'));
  if (node.hasStaleQueries) head.appendChild(el(doc, 'span', `color:${C.warn};font-size:11px;`, 'stale queries'));
  box.appendChild(head);

  const entries = Object.entries(node.state);
  if (entries.length) {
    box.appendChild(section(doc, 'state'));
    for (const [name, s] of entries) {
      // THE SMOKING GUN. A state value nothing reads is usually a binding that resolved static — the composable-param
      // class of bug, which is otherwise silent (no error, just a value that never re-renders anything). Showing the
      // count makes "why didn't this update?" a thing you can SEE rather than bisect.
      const zero = s.subscribers === 0;
      box.appendChild(kv(doc, name, short(s.value), {
        text: zero ? '0 subscribers — nothing re-renders on this' : `${s.subscribers} subs`,
        color: zero ? C.bad : C.faint,
      }));
    }
  }

  const derived = Object.entries(node.derived);
  if (derived.length) {
    box.appendChild(section(doc, 'live var'));
    for (const [name, d] of derived)
      box.appendChild(kv(doc, name, d.evaluated ? short(d.value) : '(not evaluated yet)', {
        text: d.subscribers === 0 ? '0 subscribers' : `${d.subscribers} subs`,
        color: d.subscribers === 0 ? C.bad : C.faint,
      }));
  }

  const queries = Object.entries(node.queries);
  if (queries.length) {
    box.appendChild(section(doc, 'queries'));
    for (const [name, q] of queries)
      box.appendChild(kv(doc, name, q.error ? q.error : q.loading ? 'loading…' : `${q.count ?? '?'} rows`,
        q.error ? { text: 'error', color: C.bad } : undefined));
  }

  const props = Object.entries(node.props);
  if (props.length) {
    box.appendChild(section(doc, 'props'));
    for (const [name, v] of props) box.appendChild(kv(doc, name, short(v)));
  }

  for (const child of node.children) box.appendChild(renderComponent(doc, child, depth + 1));
  return box;
}

function renderControl(doc: Document, key: string, c: ControlProbe): HTMLElement {
  const box = el(doc, 'div', `margin-top:10px;padding:8px;background:${C.row};border-radius:4px;`);
  const head = el(doc, 'div', 'display:flex;gap:8px;align-items:baseline;');
  head.appendChild(el(doc, 'span', `color:${C.text};font-weight:600;`, key));
  head.appendChild(el(doc, 'span', `color:${c.state === 'mounted' ? C.good : c.state === 'failed' ? C.bad : C.warn};font-size:11px;`, c.state));
  if (c.updateCount) head.appendChild(el(doc, 'span', `color:${C.faint};font-size:11px;`, `${c.updateCount} updates`));
  box.appendChild(head);

  if (c.error) box.appendChild(kv(doc, 'error', c.error, { text: '!', color: C.bad }));
  // C3 — mounted but painted nothing. Almost always a shim that never started its library; the control is simply
  // absent from the page, which looks identical to a layout bug or a page that didn't get that far.
  if (c.renderedNothing) box.appendChild(kv(doc, 'rendered', 'NO DOM — the element is empty', { text: 'check the shim lifecycle', color: C.bad }));
  for (const w of c.warnings) box.appendChild(kv(doc, 'warning', w, { text: '!', color: C.warn }));
  box.appendChild(kv(doc, 'package', `${c.packageHash ?? '—'} (abi ${c.contractVersion ?? '—'}, ${c.participation ?? '—'})`));

  box.appendChild(section(doc, 'last props received'));
  if (!c.lastProps) box.appendChild(kv(doc, '—', 'nothing has crossed the ABI yet'));
  else for (const [k, v] of Object.entries(c.lastProps)) box.appendChild(kv(doc, k, short(v)));

  box.appendChild(section(doc, 'events'));
  box.appendChild(kv(doc, 'bound by the app', c.boundEvents.length ? c.boundEvents.join(', ') : '(none)'));
  if (!c.events.length) box.appendChild(kv(doc, 'emitted', '(none yet)'));
  for (const e of [...c.events].reverse()) {
    // An event with no handler bound is the silent case: the control raised it and the app never heard. It looks
    // exactly like "never emitted" from the outside, so it is called out rather than listed the same.
    box.appendChild(kv(doc, e.event, short(e.payload), e.handled
      ? { text: 'handled', color: C.faint }
      : { text: 'NO HANDLER BOUND — the app never heard this', color: C.bad }));
  }
  return box;
}

function renderNet(doc: Document, p: OsyProbe): HTMLElement {
  const box = el(doc, 'div', '');
  if (!p.net.length) return box.appendChild(kv(doc, '—', 'no requests recorded')), box;
  for (const c of [...p.net].reverse()) {
    const row = el(doc, 'div', `display:flex;gap:10px;padding:3px 0;border-bottom:1px solid ${C.edge};align-items:baseline;`);
    row.appendChild(el(doc, 'span', `color:${C.dim};min-width:46px;`, c.method));
    row.appendChild(el(doc, 'span', `color:${c.error ? C.bad : C.good};min-width:38px;`, String(c.status ?? 'ERR')));
    row.appendChild(el(doc, 'span', `color:${C.text};flex:1 1 auto;word-break:break-all;`, c.url));
    row.appendChild(el(doc, 'span', `color:${C.faint};min-width:52px;text-align:right;`, `${c.ms}ms`));
    // WHAT THE SERVER DID, beside how long it took — the pair is the point. A count alone cannot say whether it was
    // worth it and a duration alone cannot say why. Tinted once the count is high enough to be worth a look: this is
    // a nudge toward the log line (which has the query SHAPES under this row's correlation id), not a verdict — a
    // report page legitimately runs many queries, and a button that runs twelve usually does not.
    if (c.db) {
      // ROUND TRIPS is the number, and it is labelled `rt` rather than `q` — the first cut said `q`, which reads as
      // "queries" and is a DIFFERENT count: a batch of 40 statements is ONE trip, so the two diverge exactly when it
      // matters. Trips are what the owner asked for and what latency is made of. Statements ride alongside, shown
      // only when they differ, because that gap IS the batching and reading `1rt` without it looks too good.
      const many = c.db.net >= 10;
      row.appendChild(el(doc, 'span', `color:${many ? C.bad : C.faint};min-width:78px;text-align:right;`,
        `${c.db.net}rt${c.db.statements > c.db.net ? `/${c.db.statements}q` : ''}`));
      row.appendChild(el(doc, 'span', `color:${C.faint};min-width:52px;text-align:right;`, `${c.db.sqlMs}ms sql`));
    }
    // The id you paste into `make logs-corr ID=…` to see the server half of this call.
    if (c.correlationId) row.appendChild(el(doc, 'span', `color:${C.accent};font-size:11px;`, c.correlationId));
    box.appendChild(row);
  }
  return box;
}

function renderData(doc: Document, p: OsyProbe): HTMLElement {
  const box = el(doc, 'div', '');
  box.appendChild(section(doc, 'loaded rows by type'));
  const loaded = Object.entries(p.data.loaded);
  if (!loaded.length) box.appendChild(kv(doc, '—', 'the store is empty'));
  for (const [type, n] of loaded.sort((a, b) => b[1] - a[1])) box.appendChild(kv(doc, type, String(n)));

  box.appendChild(section(doc, 'pending (uncommitted)'));
  const pend = p.data.pending;
  if (!pend) { box.appendChild(kv(doc, '—', 'no unit of work on this page')); return box; }
  box.appendChild(kv(doc, 'is dirty', String(pend.isDirty), pend.isDirty ? { text: 'unsaved', color: C.warn } : undefined));
  for (const [id, fields] of Object.entries(pend.dirty)) box.appendChild(kv(doc, `changed ${id.slice(0, 8)}…`, fields.join(', ')));
  if (pend.created.length) box.appendChild(kv(doc, 'created', pend.created.map((i) => i.slice(0, 8)).join(', ')));
  if (pend.deleted.length) box.appendChild(kv(doc, 'deleted', pend.deleted.map((i) => i.slice(0, 8)).join(', ')));
  if (pend.violations.length) box.appendChild(kv(doc, 'violations', short(pend.violations), { text: 'refused', color: C.bad }));
  return box;
}

function renderRoutes(doc: Document, p: OsyProbe): HTMLElement {
  const box = el(doc, 'div', '');
  box.appendChild(kv(doc, 'current path', p.routes.currentPath ?? '—'));
  box.appendChild(section(doc, 'open routes'));
  if (!p.routes.routes.length) box.appendChild(kv(doc, '—', 'no retained routes'));
  for (const r of p.routes.routes)
    box.appendChild(kv(doc, r.path, r.title ?? '(untitled)', r.isActive
      ? { text: 'active', color: C.good }
      : r.isDirty ? { text: 'dirty', color: C.warn } : undefined));
  return box;
}

function renderLogs(doc: Document, p: OsyProbe): HTMLElement {
  const box = el(doc, 'div', '');
  if (!p.logs.length) return box.appendChild(kv(doc, '—', 'no client log lines yet')), box;
  for (const l of [...p.logs].reverse()) {
    const color = l.level === 'Error' || l.level === 'Fatal' ? C.bad : l.level === 'Warning' ? C.warn : C.dim;
    const row = el(doc, 'div', `display:flex;gap:10px;padding:2px 0;align-items:baseline;`);
    row.appendChild(el(doc, 'span', `color:${color};min-width:80px;`, l.level));
    row.appendChild(el(doc, 'span', `color:${C.text};flex:1 1 auto;`, l.message));
    if (l.correlationId) row.appendChild(el(doc, 'span', `color:${C.accent};font-size:11px;`, l.correlationId));
    box.appendChild(row);
  }
  return box;
}

const TABS: { id: TabId; label: string; render: (doc: Document, p: OsyProbe) => HTMLElement }[] = [
  { id: 'components', label: 'Components', render: (d, p) => p.components ? renderComponent(d, p.components) : kv(d, '—', 'nothing mounted (a boot that failed still shows its Net tab)') },
  { id: 'controls', label: 'Controls', render: (d, p) => {
      const box = el(d, 'div', '');
      const walk = (n: ComponentProbe | null): void => {
        if (!n) return;
        for (const [k, c] of Object.entries(n.controls)) box.appendChild(renderControl(d, `${n.name}/${k}`, c));
        n.children.forEach(walk);
      };
      walk(p.components);
      if (!box.childNodes.length) box.appendChild(kv(d, '—', 'no foreign controls mounted on this page'));
      return box;
    } },
  { id: 'net', label: 'Net', render: renderNet },
  { id: 'data', label: 'Data', render: renderData },
  { id: 'routes', label: 'Routes', render: renderRoutes },
  { id: 'logs', label: 'Logs', render: renderLogs },
];

export interface DevPanel {
  toggle(): void;
  open(): void;
  close(): void;
  readonly isOpen: boolean;
  /** Re-render from a fresh snapshot. */
  refresh(): void;
  destroy(): void;
}

/** Install the Ctrl+Shift+D panel. `probe` is the SAME builder `dump()` uses — that is the whole design. */
export function installDevPanel(probe: () => OsyProbe, doc: Document): DevPanel {
  let host: HTMLElement | null = null;
  let body: HTMLElement | null = null;
  let tab: TabId = 'components';
  let open = false;

  const build = (): void => {
    host = el(doc, 'div', `position:fixed;left:0;right:0;bottom:0;height:45vh;z-index:2147483647;background:${C.bg};`
      + `border-top:2px solid ${C.accent};color:${C.text};font:12px/1.5 ${MONO};display:flex;flex-direction:column;`
      + `box-shadow:0 -8px 30px rgba(0,0,0,.45);`);
    host.setAttribute('data-osy-devpanel', '');

    const bar = el(doc, 'div', `display:flex;gap:4px;align-items:center;padding:6px 8px;background:${C.bar};border-bottom:1px solid ${C.edge};flex:0 0 auto;`);
    bar.appendChild(el(doc, 'span', `color:${C.accent};font-weight:700;margin-right:8px;`, 'osy'));
    for (const t of TABS) {
      const b = el(doc, 'button', tabStyle(t.id === tab), t.label);
      b.addEventListener('click', () => { tab = t.id; render(); });
      bar.appendChild(b);
    }
    const spacer = el(doc, 'span', 'flex:1 1 auto;');
    bar.appendChild(spacer);
    const refreshBtn = el(doc, 'button', tabStyle(false), 'Refresh');
    refreshBtn.addEventListener('click', () => render());
    bar.appendChild(refreshBtn);
    const closeBtn = el(doc, 'button', tabStyle(false), 'Close');
    closeBtn.addEventListener('click', () => api.close());
    bar.appendChild(closeBtn);

    body = el(doc, 'div', 'overflow:auto;padding:10px 12px;flex:1 1 auto;');
    host.appendChild(bar);
    host.appendChild(body);
    doc.body.appendChild(host);
  };

  const tabStyle = (active: boolean): string =>
    `background:${active ? C.accent : 'transparent'};color:${active ? '#08111f' : C.dim};border:1px solid ${active ? C.accent : C.edge};`
    + `border-radius:4px;padding:3px 9px;font:11px ${MONO};cursor:pointer;`;

  const render = (): void => {
    if (!host || !body) return;
    // Rebuild the bar so the active tab highlights, then the body from a FRESH snapshot.
    const bar = host.firstChild as HTMLElement;
    const buttons = Array.from(bar.querySelectorAll('button'));
    TABS.forEach((t, i) => buttons[i]?.setAttribute('style', tabStyle(t.id === tab)));

    const p = probe();
    body.textContent = '';

    const head = el(doc, 'div', `color:${C.faint};padding-bottom:6px;border-bottom:1px solid ${C.edge};margin-bottom:6px;`);
    head.textContent = `${p.app.slug ?? '(no slug)'} · ${p.app.component ?? '—'} · ${p.app.path ?? '—'}`;
    body.appendChild(head);

    body.appendChild((TABS.find((t) => t.id === tab) ?? TABS[0]).render(doc, p));
  };

  const onKey = (e: Event): void => {
    const k = e as unknown as { ctrlKey?: boolean; shiftKey?: boolean; key?: string; preventDefault?: () => void };
    if (k.ctrlKey && k.shiftKey && (k.key === 'D' || k.key === 'd')) {
      k.preventDefault?.();
      api.toggle();
    }
  };

  const api: DevPanel = {
    get isOpen() { return open; },
    open() {
      if (open) return;
      if (!host) build();
      else doc.body.appendChild(host);
      open = true;
      render();
    },
    close() {
      if (!open) return;
      host?.parentNode?.removeChild(host);
      open = false;
    },
    toggle() { open ? api.close() : api.open(); },
    refresh() { if (open) render(); },
    destroy() { api.close(); doc.removeEventListener('keydown', onKey); host = null; body = null; },
  };

  doc.addEventListener('keydown', onKey);
  return api;
}
