// Locale slice 2c — the app's DECLARED zones' DST plans, projected out of the AMM the server serves at
// `GET /api/metadata` (the same channel as the culture plans, model-cultures.ts). A zone operation ships as a `zone*`
// node carrying only the IANA TOKEN (the plan is large and shared across call sites); the interpreter and the render
// evaluator look the token's plan up HERE and run the DST engine (zone-math.ts) in-process. The token was proved
// DECLARED at compile time, so its plan is always present — a miss is a wiring bug (the model didn't load), surfaced
// loudly, never a silent wrong offset.

import type { MetadataModelDto } from './model-dto.js';
import type { ZoneFormatPlan } from '../runtime/zone-math.js';

/** IANA token → the zone's DST plan. */
export type ZoneStore = Record<string, ZoneFormatPlan>;

export const EMPTY_ZONES: ZoneStore = {};

/** Project the served zones into a token-keyed store. */
export function projectZones(model: MetadataModelDto): ZoneStore {
  const store: ZoneStore = {};
  for (const z of model.zones ?? []) store[z.zone] = z;
  return store;
}

/** The DST plan for a declared zone token. Throws if the token is absent — it was compile-validated as declared, so a
 *  miss means the app's model did not load (a wiring bug), which must fail loudly, not resolve to a wrong offset. */
export function zonePlan(store: ZoneStore, token: string): ZoneFormatPlan {
  const z = store[token];
  if (!z) throw new Error(`zone '${token}' has no DST plan — the app's model wasn't loaded (zones channel).`);
  return z;
}
