/** The server → client handoff embedded in the boot shell (mirrors UiPageEndpoints.BootDescriptor). */
export interface BootDescriptor {
  component: string;
  params: Record<string, string>;
  /** Secure by default: true (= the page is not [AllowAnonymous]) → redirect an unauthenticated visitor to login. */
  requiresAuth: boolean;
  appSlug: string | null;
  /** The app's DECLARED login route (from `app.AuthBootstrap { LoginPage = … }`), so the redirect targets a real
   *  page instead of guessing `/login`. Null/absent when the app declared no login page → the `/login` fallback. */
  loginRoute?: string | null;
  /** D28 — the content address of the app's icon sprite, or null when it ships no icons. The served shell already
   *  INLINES the sprite, so this is only used when the client is mounted OUTSIDE that shell (a preview, a test
   *  harness): fetch it once and inject it, so `<use href="#osy-icon-x">` stays same-document. */
  iconSpriteHash?: string | null;
  /** D102 — the content address of the app's SVG-asset set, or null when it ships none. SSR already inlined each asset
   *  at its site; the client fetches this map (once, immutable) so a CLIENT-side render (a navigation to a page the
   *  server didn't prerender) can inline an asset. Public, same-origin chrome — not authorization detail. */
  svgAssetsHash?: string | null;
  /** D232 — the content address of the app's TEXTURE set, or null when it ships none. Unlike the SVG assets there is
   *  no SSR half to fall back on: a texture is only ever painted onto a canvas, and a canvas is only ever painted by
   *  client code — so this map is the ONLY way the client learns what `Draw.Image(wall, …)` means. Public,
   *  same-origin chrome (art the app ships), carrying no authorization detail. */
  texturesHash?: string | null;
  /** The minimum level of client-written log line to FORWARD to the server (app-logging L8). The SERVER's floor is the
   *  authoritative one — it re-checks on ingest — so this only saves the browser from sending lines that would be
   *  dropped on arrival. Absent → forward everything. */
  clientLogFloor?: string | null;
  /** Whether this HOST records execution traces (inspect Slice B) — true only on the local dev server. The client
   *  gates its trace recording + posting on it: a deployed process has no trace ring and would discard the segment, so
   *  it never builds or sends one. Absent → false (don't record). */
  traceEnabled?: boolean;
  /** Whether this host pushes recompile signals a mounted page can hot-swap on — true only on the local dev server.
   *  When set, the client opens a live-reload WS even for an ANONYMOUS page (the dev server, and only it, accepts an
   *  anon WS), so a recompile updates the open page without a hard-refresh. Absent → false (no anon live-reload). */
  liveReload?: boolean;
  /** The app's whole routing surface (D23 Phase 1), so the client router resolves an in-app navigation with no
   *  server round-trip. Public metadata carrying no authorization detail — see `routes.ts`. */
  routes?: RouteEntry[];
  /** The app's declared connection-loss surface component (`app.Ui { ConnectionSurface = … }`), or null/absent when
   *  none — the client then uses its built-in overlay. Boot pre-fetches this component's tree (while the server is
   *  alive) and mounts it (against the `Connection` ambient) as a fixed overlay when the server drops. A public
   *  component name, no authorization detail. */
  connectionSurface?: string | null;
  /** D118 — the busy-spinner timing config (`app.Ui { PendingDelayMs / PendingMinShowMs }`). 0/absent → the client
   *  defaults (200 / 300). A control whose action suspends shows a spinner after `pendingDelayMs` and keeps it at least
   *  `pendingMinShowMs`. Pure config, no authorization detail. */
  pendingDelayMs?: number;
  pendingMinShowMs?: number;
  /** D118 — the app's own spinner component name (`app.Ui { PendingIndicator = … }`), mounted inside a pending control
   *  instead of the built-in `.osy-spinner`, or null/absent → the default. A public component name. */
  pendingIndicator?: string | null;
}

/** The id the server gives the inlined sprite element. Mirrors UiIconSprite.SpriteElementId. */
const ICON_SPRITE_ID = 'osy-icon-sprite';

/** D28 — ensure the icon sprite is in the document. The served shell inlines it, so this is a NO-OP on a normal page
 *  load; it only fetches when the client mounted outside the shell. Failure is non-fatal: icons are chrome, and an
 *  app must not fail to boot because a decorative sprite 404'd. The bytes were sanitized at compile time
 *  (SECURITY-INVARIANT(ui-icon-sanitize)) and are served same-origin, immutable, under a content address. */
export async function ensureIconSprite(doc: Document, opts: BootOptions, hash?: string | null): Promise<void> {
  if (!hash || doc.getElementById(ICON_SPRITE_ID)) return;
  try {
    const http = opts.fetch ?? fromGlobalFetch();
    const res = await http(`${opts.baseUrl ?? ''}/_osy/icons/${encodeURIComponent(hash)}.svg`, { method: 'GET' });
    if (!res.ok || !res.text) return;
    const svg = await res.text();
    // A <use> resolves against the DOM, so the sprite has to be parsed as SVG and adopted — not assigned as the
    // innerHTML of an HTML element, which would give the symbols the wrong namespace and silently render nothing.
    const parsed = new DOMParser().parseFromString(svg, 'image/svg+xml');
    const root = parsed.documentElement;
    if (!root || root.nodeName === 'parsererror' || doc.getElementById(ICON_SPRITE_ID)) return;
    doc.body.insertBefore(doc.importNode(root, true), doc.body.firstChild);
  } catch {
    // Non-fatal by design.
  }
}

/** D102 — fetch the app's SVG-asset set (name → sanitized `<svg>`) and install it into the render walker, so a
 *  CLIENT-side render of a `Svg(name)` inlines the asset. A no-op when the app ships none. SSR already inlined each
 *  asset into the served HTML, so this only matters for a client-rendered navigation; failure is non-fatal (assets are
 *  chrome). The bytes were sanitized at compile time (SECURITY-INVARIANT(ui-svg-asset-sanitize)), served same-origin,
 *  immutable, under a content address — the walker inlines them via `image/svg+xml` parsing, never as HTML. */
export async function ensureSvgAssets(opts: BootOptions, hash?: string | null): Promise<void> {
  if (!hash) return;
  try {
    const http = opts.fetch ?? fromGlobalFetch();
    const res = await http(`${opts.baseUrl ?? ''}/_osy/svg/${encodeURIComponent(hash)}.json`, { method: 'GET' });
    if (!res.ok || !res.text) return;
    const map = JSON.parse(await res.text()) as Record<string, string>;
    if (map && typeof map === 'object') setSvgAssets(map);
  } catch {
    // Non-fatal by design.
  }
}

/** D232 — fetch the app's texture map (name → url + intrinsic size) and install it into the render walker, so a
 *  `Draw.Image(wall, …)` knows which bytes to blit. A no-op when the app ships none.
 *
 *  <p>Unlike the SVG assets, failure here is NOT cosmetic — a canvas that cannot find its art draws nothing — but it
 *  still must not take the boot down: a game whose textures 404 should reach the page and SAY so (the walker reports
 *  the first miss per name) rather than show a boot error the user cannot act on. The map is public, same-origin,
 *  immutable, under a content address; the bytes it points at are served under the type sniffed from them at compile
 *  time (SECURITY-INVARIANT(ui-texture-content-type)).</p> */
export async function ensureTextures(opts: BootOptions, hash?: string | null): Promise<void> {
  if (!hash) return;
  try {
    const http = opts.fetch ?? fromGlobalFetch();
    const res = await http(`${opts.baseUrl ?? ''}/_osy/textures/${encodeURIComponent(hash)}.json`, { method: 'GET' });
    if (!res.ok || !res.text) return;
    const map = JSON.parse(await res.text()) as Record<string, OsyTexture>;
    if (map && typeof map === 'object') setTextures(map);
  } catch {
    // Non-fatal by design — see above.
  }
}

export interface BootOptions {
  doc?: Document;
  /** Mount host; default the #app element. */
  host?: Element | null;
  baseUrl?: string;
  fetch?: HttpFetch;
  /** Live-data channel transport; omitted → live queries degrade to plain queries. */
  ws?: WsTransport;
  /** WHAT TIME IT IS, for `Now.Utc` and everything that advances with it. Omitted → the wall clock. */
  clock?: { now(): number; onChange?(cb: () => void): () => void };
  /** HOW TO LOAD A MODULE BY URL, for a host whose own `import()` will not take one — a node process running the real
   *  client cannot import over http, so without this a foreign control cannot load there at all. Omitted → a plain
   *  dynamic `import()`, which is what a browser does and what production always uses. */
  loadModule?: (url: string) => Promise<unknown>;
  /** Token source; default: a stored app token, else an anonymous launch. Return null → no credential. */
  getToken?: (descriptor: BootDescriptor) => Promise<string | null>;
  /** Navigate the browser (for the login redirect); default location.assign. */
  redirect?: (url: string) => void;
  /** Override the login route the redirect targets. Precedence: this → the descriptor's declared `loginRoute` →
   *  '/login'. */
  loginRoute?: string;
  /** The path to return to after login (rides the redirect as `?returnTo=`); default the current location. */
  currentPath?: string;
  /** The client router's browser surface (D23 Phase 1b). Default: the real browser one, or none outside a browser.
   *  Pass `null` to boot WITHOUT a router (hard navigations only). */
  routerEnv?: RouterEnv | null;
  /** Receives the started router, when one was wired. The seam for programmatic navigation (and for a test to
   *  dispose it — a router holds a delegated listener on the document). */
  onRouter?: (router: Router) => void;
  /** The connection-loss surface renderer (server dropped mid-session). Default: the built-in overlay. An app supplies
   *  its own via `app.Ui.ConnectionSurface`, wired here. Called on every state change with the recovery actions. */
  connectionRender?: (state: ConnState, ctx: { attempts: number; retry: () => void; reload: () => void }) => void;
  /** Receives a reader for "how many action interactions are in flight" — the seam a host uses to know whether the app
   *  is BUSY. Handed as a READER rather than pushed as events so the caller polls when it cares and nothing is
   *  retained on its behalf; the root is late-bound (the router mounts after boot), so the reader answers 0 until
   *  there is one. Available on every host, unlike the dev handle. */
  onActivity?: (inFlight: () => number) => void;
  /** ⭐ How many activations this page has EVER started — monotonic, so a DIFFERENCE across an interaction answers
   *  "did that click actuate anything" without racing the action.
   *
   *  ⛔ `onActivity` CANNOT ANSWER THAT QUESTION, and reading it as if it could is what made the driver accuse live
   *  controls of being dead: it is in-flight-NOW, so an action that finishes inside the dispatch turn is already
   *  back to 0 by the time a host samples it. Same shape and same reasoning as `onActivity` otherwise. */
  onActionsStarted?: (started: () => number) => void;
  /** ⭐ How many actions are PARKED on a dialog, waiting for an answer only the user can give — see
   *  `ComponentInstance.dialogAwaits`.
   *
   *  ⛔ A HOST CANNOT ASK THE DOM THIS, and the one that tried turned a correct wait into a timer. `Dialog.Ask`
   *  suspends its action until `Dialog.Confirm(value)` settles it, so the driver — which is the only thing that can
   *  supply that click — must stop waiting for that action to drain. It decided by counting modals on screen, which
   *  also fires for the ordinary app dialog an action is in the middle of CLOSING: the modal is still up while the
   *  commit inside `Confirm` is in flight. So the wait that spans a write returned before the write did. This
   *  reader answers the state instead of the picture. */
  onDialogAwaits?: (parked: () => number) => void;
  /** How many navigations are REQUESTED but not yet landed — see `Router.navsInFlight`. Same shape and same
   *  reason as `onActivity`: a harness cannot ask the DOM whether a route change is still on its way. */
  onNavActivity?: (inFlight: () => number) => void;
  /** How many list flushes are SCHEDULED and not yet run — the difference between "the data arrived" and "the screen
   *  shows it". Same shape and same reason as the two above, one door further along: a live list coalesces appends
   *  into one flush on the next animation frame, so in a real browser the network can be quiet, the store full, and
   *  the DOM still showing the previous screen. A driver that stops at network-quiet then reads the old page and
   *  blames the app. See `liveListFlushesPending`, which this hands over. */
  onRenderPending?: (pending: () => number) => void;
  /** M180 — READ what the form is currently refusing: the model's declared rules judged against the pending edits,
   *  filtered to what the person has actually been shown. Same reasoning as `onActivity` and deliberately NOT on the
   *  dev handle: why a form refuses is not a debug fact, and a consumer built on `__osy` would work against a dev
   *  server and silently answer nothing everywhere else. */
  onValidation?: (violations: () => readonly { Entity: string; Field: string; Rule: string; Message: string }[]) => void;
  /** M199 — READ WHAT EACH MOUNTED CONTROL SAYS ABOUT ITSELF: the `probe { }` fields its author declared, answered by
   *  its shim on demand. The seam a UI test driver asks `Assert.Probe(control, field, expected)` through.
   *
   *  ⚠ DELIBERATELY NOT ON THE DEV HANDLE, and this is the trap it exists to avoid. `__osy.controls` already
   *  aggregates control probes and is the obvious shortcut — but `__osy` is gated on the boot descriptor's
   *  `traceEnabled`, which is TRUE on a local dev server and FALSE on the in-process test host. A driver built on it
   *  would work under `osy test`, where a demo is written, and silently answer nothing under the suite that runs it:
   *  the exact "passes where you develop it, fails where it runs" split. Same reasoning as `onActivity` above.
   *
   *  Handed as a READER rather than pushed as events, for the same reason those are: a probe is what is true at the
   *  moment somebody asks, so anything retained on the caller's behalf would be stale by the time it was read. */
  onControlProbes?: (read: () => readonly ControlProbeReading[]) => void;
  /** How many mounted components are showing their `skeleton { }` — see `ComponentInstance.skeletonsShowing`. */
  onSkeletons?: (read: () => number) => void;
  /** Has the app asked the browser to LEAVE this page? — see `runtime/navigating`. A headless driver needs it for
   *  the same reason the logger does: after a sign-in the most successful action an app has ends in a full page
   *  load, and everything observed before that load describes a page that is on its way out. */
  onLeaving?: (read: () => boolean) => void;
  /** Has the CLIENT completed its first mount? — see `firstMountDone`. Ungated, for the same reason as the readers
   *  around it: whether the app has actually rendered is not a debug fact. */
  onBooted?: (read: () => boolean) => void;
}

/** Read the boot descriptor the served shell embedded. Throws loudly if the shell is malformed — a missing
 *  descriptor means the wrong page was served, never a silent blank mount. */
export function readBootDescriptor(doc: Document): BootDescriptor {
  const el = doc.getElementById('osy-boot');
  const json = el?.textContent;
  if (!json) throw new Error('osy boot descriptor (#osy-boot) not found in the served shell');
  return JSON.parse(json) as BootDescriptor;
}

/** C.3-2-perf — the anon query rows an SSR route embedded in the shell (`#osy-ssr-data`), keyed by rootId. Present
 *  only for a server-rendered page with query data; absent for a CSR route or a static SSR page. Malformed → null
 *  (never fatal: the client just boots with `data=1` and fetches the rows itself). */
export function readSsrData(doc: Document): Record<string, QueryResult> | null {
  const el = doc.getElementById('osy-ssr-data');
  const json = el?.textContent;
  if (!json) return null;
  try {
    return JSON.parse(json) as Record<string, QueryResult>;
  } catch {
    return null;
  }
}

/** Read an app.Ui boot-failure surface (Forbidden/Error) the server INLINED into the shell as a client wire tree
 *  (`<script id="osy-surface-…">`). In hand at boot with no fetch, so `handleBootFailure` can mount it even for a
 *  refusal that happened before the session opened (or while the server is flaky). Absent/malformed → null (the client
 *  then uses its built-in boot-error surface). */
export function readInlinedSurface(doc: Document, id: string): ComponentTree | null {
  const json = doc.getElementById(id)?.textContent;
  if (!json) return null;
  try {
    return JSON.parse(json) as ComponentTree;
  } catch {
    return null;
  }
}

/** The boot currently running for a given host. ONE at a time, and the reason is a bug that has no other guard.
 *
 *  `hydrate` is sampled from `host.childNodes.length > 0` — so two boots that OVERLAP both read the host as empty,
 *  both decide to build fresh, and each appends a complete page into it. The result is the whole app rendered twice,
 *  one copy below the other, with live data in both (FL/M-11's reported symptom). Nothing downstream can catch it:
 *  each boot has its own session, its own router and its own queue, and neither is doing anything wrong on its own.
 *
 *  A WeakMap keyed by the host, cleared when the boot settles — so it dedupes exactly the overlap and nothing else.
 *  A SEQUENTIAL second boot is left alone deliberately: by then the first has painted, `hydrate` reads true, and the
 *  second adopts (or bails out, clearing first). That case does not double and is legitimately how a host re-boots. */
const bootsInFlight = new WeakMap<Element, Promise<ComponentInstance | null>>();

/** ⛔ HAS THE CLIENT FINISHED ITS FIRST MOUNT? — the one thing a headless reader could not ask, and the reason it
 *  read half-built pages.
 *
 *  <p>Every other signal starts at ZERO and is satisfied by zero: no actions in flight, no navigations, no
 *  subscriptions, no controls mounting. Before boot runs, all of them say "idle" — and on a server-rendered page the
 *  DOM is not empty either, because the SERVER painted the shell. So "the page has content" is true from the first
 *  byte, and the client then CLEARS the outlet to build its own tree. A driver reading in that window sees a perfect
 *  shell around an empty pane, which is exactly what it reported.</p>
 *
 *  <p>⚑ MEASURED 2026-08-31 on `osy-crm` under `--pixels`, 3 failures in 4 full-suite runs while every one of those
 *  tests passed 6/6 in isolation: the layout rendered, the outlet was empty, and the nav item for the route was not
 *  even highlighted. Module state, so a hard navigation (a new document) starts false again — which is correct: each
 *  document boots once.</p> */
let firstMountDone = false;

/** How to stop the boot running in a given host, registered by `boot()` once its machinery exists.
 *
 *  A boot builds a router (listening on `document` for every click and on `popstate`), a connection monitor, a
 *  metadata subscription and a global error capture — and every one of those teardowns used to be discarded at its
 *  call site. The caller was handed a `ComponentInstance`, and from there the machinery around it was unreachable:
 *  there was no expression, anywhere, that stopped a booted page. In a browser tab that is invisible, because the tab
 *  takes it all with it; it stops being invisible the moment a document OUTLIVES a boot — a re-boot, an embedded
 *  host, a test file that boots more than once. The leaked router keeps intercepting in-app clicks and navigating a
 *  host nothing renders into any more, so the visible page simply stops responding. */
const bootTeardowns = new WeakMap<Element, () => void>();

/** Stop the boot running in `host` — its router, its connection monitor, its metadata subscription, its global error
 *  capture, and the page itself (the router disposes what it mounted).
 *
 *  <p>A no-op for a host that has no boot, so it is safe to call defensively. Idempotent: the entry is dropped as it
 *  runs.</p>
 *
 *  <p>Production never needs this — a page load ends with the tab. It exists for the hosts where a document outlives
 *  a boot, and the first of those is the test suite: without it, an earlier test's router intercepts a later test's
 *  clicks against a detached host, which passes alone and fails second and reads exactly like a flake.</p> */
export function disposeBoot(host?: Element | null): void {
  const target = host ?? document.getElementById('app');
  if (!target) return;
  const teardown = bootTeardowns.get(target);
  if (!teardown) return;
  bootTeardowns.delete(target);
  teardown();
}

/** Boot the served page. Returns the mounted instance, or null when it redirected to login instead of mounting.
 *
 *  Calling it again while a boot of the same host is still running returns THAT boot rather than starting a second —
 *  see `bootsInFlight`. Deduped rather than thrown: the caller asked for a booted page on this host and there is one
 *  coming, so handing it over is the correct answer, and throwing would take down a page that merely got double-invoked
 *  (a script included twice). The warning is what makes it visible. */
export function boot(opts: BootOptions = {}): Promise<ComponentInstance | null> {
  const host = opts.host ?? (opts.doc ?? document).getElementById('app');
  if (!host) throw new Error('osy boot host (#app) not found in the served shell');

  const inFlight = bootsInFlight.get(host);
  if (inFlight) {
    console.warn('[osy] boot() was called again while the first boot of this host was still running — returning the '
      + 'boot already in progress. Two overlapping boots each read the host as empty and each build a whole page '
      + 'into it, which renders the app twice.');
    return inFlight;
  }

  const started = bootIntoHost(host, opts).finally(() => { bootsInFlight.delete(host); });
  bootsInFlight.set(host, started);
  return started;
}

async function bootIntoHost(host: Element, opts: BootOptions = {}): Promise<ComponentInstance | null> {
  const doc = opts.doc ?? document;
  const descriptor = readBootDescriptor(doc);
  // EVERY boot-scoped teardown, collected as it is created and tied to the mounted page at the end. Each of these
  // used to be discarded at its call site — so a booted page left a router listening on `document`, a connection
  // monitor pinging, a metadata subscription live and a global error capture installed, with no way for ANY caller to
  // stop them: `boot()` hands back a ComponentInstance and the machinery around it was unreachable from there.
  const teardowns: (() => void)[] = [];



  // OAuth login handoff: the server's `/api/oauth/callback` provisions/authenticates the app User and redirects the
  // browser back to the app carrying the signed app ticket as `oauth_token`. Consume it into the stored token BEFORE
  // the normal token read (so this boot mounts authenticated), then strip it from the URL so the ticket isn't left in
  // history/referrer. Mirrors `Session.SignIn`'s writeStoredToken — the ticket is a courier, re-verified server-side.
  consumeOAuthCallbackToken(opts);

  // The app's boot-failure surfaces (app.Ui.ForbiddenSurface / ErrorSurface), inlined by the server as client wire
  // trees — read NOW so `handleBootFailure` can mount them even for a failure before the session opens. Null → the
  // built-in boot-error surface.
  const bootSurfaces: BootSurfaces = {
    forbidden: readInlinedSurface(doc, 'osy-surface-forbidden'),
    error: readInlinedSurface(doc, 'osy-surface-error'),
  };

  // D28 — a no-op when the shell inlined the sprite (the normal path); a single immutable fetch otherwise.
  await ensureIconSprite(doc, opts, descriptor.iconSpriteHash);
  // D102 — fetch the SVG-asset map so a client-rendered `Svg(name)` can inline the asset (a no-op when none).
  await ensureSvgAssets(opts, descriptor.svgAssetsHash);
  await ensureTextures(opts, descriptor.texturesHash);

  // Re-authenticating must start from a CLEAN session. An [AuthMethod] (Login/Signup) only arms the ephemeral
  // Authenticator principal for an UNAUTHENTICATED caller — a deliberate server anti-escalation (AuthBootstrapContext
  // .ShouldArmFor). So if a lingering session is present, Login runs as the OLD user (whose row-scoped read can't even
  // find the account being logged into), returns "", and the user lands anonymous → the authed layout 403s → a
  // dead-end "no access". Landing on the app's DECLARED login route means the user intends to (re)authenticate, so drop
  // any stored token here: this boot is anonymous and the auth-method call arms + succeeds, then SignIn stores the new
  // ticket. (An accidental visit to /login by a signed-in user therefore re-shows the form — the expected, recoverable
  // outcome of navigating to the login page.)
  const bootPath = opts.currentPath ?? defaultCurrentPath();
  if (descriptor.loginRoute && isSameRoute(bootPath, descriptor.loginRoute) && readStoredToken()) clearStoredToken();

  const token = await (opts.getToken ?? defaultGetToken(opts))(descriptor);
  if (!token) {
    // No credential. A protected page (secure by default) can't render for an anon — send them to log in (the
    // real auth teeth are server-side; this is just so the user lands somewhere useful, not a forbidden fetch).
    if (descriptor.requiresAuth) {
      // Redirect to the app's DECLARED login route (an override wins, then the descriptor's, then '/login'), carrying
      // a return-to so login can send the now-authenticated user back to the page they wanted.
      const route = opts.loginRoute ?? descriptor.loginRoute ?? '/login';
      const returnTo = opts.currentPath ?? defaultCurrentPath();
      (opts.redirect ?? defaultRedirect)(withReturnTo(route, returnTo));
      return null;
    }
    throw new Error(`no session token available to boot page '${descriptor.component}'`);
  }

  // The live-data channel: an explicit transport wins; otherwise build a browser WebSocket one — for an app-scoped
  // token, OR (on the local dev server, per `liveReload`) an anon one, so an anon page hot-reloads on recompile. In
  // production the server 403s an anon WS and `liveReload` is false, so this stays app-scoped-only.

  // The first page is KNOWN before the context is opened — the shell's route manifest named it. So the boot asks for
  // it by name and gets the context, the tree and the data in ONE turn (D53-e).
  const bootMatch = matchRoute(descriptor.routes ?? [], opts.currentPath ?? defaultCurrentPath());
  const bootComponent = bootMatch?.entry.component ?? descriptor.component;
  const bootParams = bootMatch?.params ?? {};
  // …and so is every OTHER tree this boot will mount (M242): the route's LAYOUT, from the manifest, and the app's
  // declared CONNECTION SURFACE, from the descriptor. Both are named before the context exists, so both can be asked
  // for in the same turn instead of being discovered only when something goes to mount them — which is what made
  // each of them its own round trip.
  const bootAlso = [bootMatch?.entry.layout, descriptor.connectionSurface].filter((n): n is string => !!n);

  // A 401 on ANY authed request means the stored ticket is stale — the server was restarted (a new signing key), the
  // DB was reset, or the token expired. The client held the token, so the auth GATE thought it was signed in and
  // mounted the page instead of redirecting; then every fetch 401'd and nothing loaded — a dead blank page. This
  // interceptor is the single chokepoint that fixes it for every authed call (the boot context-open, a later query,
  // a `/ui` tree, an action's server call): a real 401 is what PROVES the token stale, so it drops the ticket and
  // sends the user to log in. Guarded to redirect once even when a page fires many requests at once.
  const onUnauthorized = makeUnauthorizedHandler(opts, descriptor);
  // Built here (not earlier) so it can hand the live channel the SAME re-auth handler every other 401 uses: when the
  // WS upgrade is refused repeatedly the session is gone, and that must land the user on login rather than leave a
  // page that renders fine and silently never updates again.
  const ws = opts.ws ?? defaultWs(token, descriptor.liveReload ?? false, onUnauthorized);
  // Server-loss surface: a monitor fed by the transport. A network reject or a gateway status (>= 502) means the
  // server dropped — it flips to `reconnecting`, pings a cheap always-served asset with backoff, escalates to `lost`,
  // and clears the moment anything succeeds. The router already rolls a failed navigation back (no teardown); this
  // tells the user and offers Retry/Reload. A 401 is NOT loss (the server answered) — `onUnauthorized` still owns it.
  const rawFetch = opts.fetch ?? fromGlobalFetch();
  const connection = new ConnectionMonitor({
    ping: async () => {
      try { const r = await rawFetch(`${opts.baseUrl ?? ''}/_osy/client.js`, { method: 'HEAD' }); return r.status < 500; }
      catch { return false; }
    },
    render: opts.connectionRender,   // app-supplied surface (app.Ui.ConnectionSurface) when present; else the default
    reload: opts.redirect ? () => opts.redirect!(defaultCurrentPath() || '/') : undefined,
  });
  // DEV HOST ONLY (`traceEnabled` is documented as "true only on the local dev server", the same bit that gates trace
  // recording). A deployed app takes neither the rings nor the fetch decorator — production pays nothing. The
  // connection monitor wraps first (it must see every request's outcome); the dev recorder is the outermost decorator.
  const devHost = descriptor.traceEnabled === true;
  const netRing = new Ring<NetProbe>(100);
  const monitored = monitorConnection(interceptUnauthorized(rawFetch, onUnauthorized), connection);
  const fetchImpl = devHost ? recordingFetch(monitored, netRing) : monitored;

  // C.3-2-perf — the SSR shell embedded the anon rows it already computed. An ANONYMOUS client seeds them and opens its
  // context WITHOUT `data=1`, so those queries run once (in the SSR request), not again on the context-open. An
  // AUTHENTICATED visitor (an app-scoped token) does NOT seed the anon rows: it may see a different set, so it keeps
  // `data=1` and fetches its own — exactly as before (C.3-1's hydration mismatch-rebuild then reconciles the SSR DOM).
  const ssrData = readSsrData(doc);
  const seededData = ssrData && jwtScope(token) !== 'application' ? ssrData : undefined;

  // ⚠ THE STDLIB'S CLOCK, which is a SECOND one and was not pinnable. `DateTime.UtcNow` inside a `live var`
  // computed — how an app asks "is this due yet" on a page — resolves through the runtime stdlib, whose
  // `OsyDateTime.utcNow()` read `Date.now()` directly. So a host that pinned time moved the walker's `Now` ambient
  // and left every stdlib clock read on the wall clock. Measured 2026-08-19 (ledger H-15): `TestClock.Advance(2h)`
  // expired a row in the server's memory and left the same row live on screen.
  OsyDateTime.useHostClock(opts.clock ? () => opts.clock!.now() : null);

  let session: PlatformSession;
  try {
    session = await PlatformSession.open({
      token,
      baseUrl: opts.baseUrl,
      fetch: fetchImpl,
      ws,
      // M179 — the host's clock, when it has one. A preview scrubbing a timeline, a replay, or a test proving a
      // countdown reaches zero without waiting for it: all the same need, and none of them the machine's clock.
      //
      // ⚠ AND THE STDLIB NEEDS IT TOO — see the `useHostClock` call below. Passing it here reaches the walker's
      // `Now` ambient and nothing else, which left the client with two clocks and only one of them pinnable.
      ...(opts.clock ? { clock: opts.clock } : {}),
      ...(opts.loadModule ? { loadModule: opts.loadModule } : {}),
      signIn: makeSignIn(opts, descriptor),
      signOut: makeSignOut(opts, descriptor),
      // L8 — the server decides how chatty the browser should be (everything locally, Warning+ in cloud). It re-checks
      // the floor on ingest regardless; this just saves us sending lines that would be dropped on arrival.
      clientLogFloor: descriptor.clientLogFloor ?? undefined,
      // inspect Slice B — only the local dev server can trace; the client records + posts its trace segment only then.
      traceEnabled: descriptor.traceEnabled ?? false,
      // D118 — the app's busy-spinner timing + custom spinner (app.Ui). 0/absent → the client defaults.
      pendingDelayMs: descriptor.pendingDelayMs ?? 0,
      pendingMinShowMs: descriptor.pendingMinShowMs ?? 0,
      pendingIndicator: descriptor.pendingIndicator ?? null,
    }, bootComponent ? { component: bootComponent, also: bootAlso, params: bootParams, seededData } : undefined);
  } catch (err) {
    // The context-open is the FIRST authed request, and it runs before the mount try/catch below. A stale ticket 401s
    // it — and the fetch interceptor already cleared the token and redirected — so bail cleanly instead of rejecting
    // boot with an error nobody catches (which was the blank-page half of the bug). A 403 here is the login `returnTo`
    // trap surfacing at open (an authed caller sent back to a page THIS account can't see): render the SAME
    // access-denied surface with the home escape as the mount path, never a blank page. Any other open() failure is real.
    if (err instanceof OsyHttpError && err.status === 401) return null;
    if (err instanceof OsyHttpError && err.status === 403) return await handleBootFailure(host, err, onUnauthorized, descriptor, bootSurfaces);
    throw err;
  }

  // Capture the errors that escape everything else. A failing ACTION is already logged where it happens (the walker
  // knows the interaction's correlation id there); this catches what is thrown OUTSIDE one — a stray promise
  // rejection, an error in a render callback or a foreign control — which until now went to the console and NOWHERE
  // else. Those are exactly the failures nobody is watching for, on a machine you cannot reach.
  const globals = (opts.doc ?? document).defaultView;
  if (globals) {
    teardowns.push(captureGlobalErrors(session.logger, globals as unknown as ErrorCaptureTarget));
    // Drain the buffer when the page goes away: a batch still in memory dies with the tab, and the lines you lose that
    // way are the ones written just before the user left — usually exactly when it broke. `pagehide` (not `unload`)
    // is the event that actually fires on mobile.
    globals.addEventListener('pagehide', () => { markNavigating(); void session.logger.flush(); });
  }

  // Server-loss surface, app half (slice 3c): when the app declared `app.Ui.ConnectionSurface`, pre-fetch that
  // component's tree NOW (while the server is alive) and install a renderer that mounts it — bound to the `Connection`
  // ambient — as a fixed overlay when the monitor reports a drop. Replaces the built-in default overlay. A no-op when
  // the app declared none (the default overlay stays). Failure to pre-fetch is non-fatal: the default overlay remains.
  await wireConnectionSurface(descriptor, session, connection, opts, doc);

  // The `Navigation` capability (D29): the router as Osy# sees it. Declared BEFORE the router so `mount` can close
  // over it, and reads `router` lazily — the first read happens during a render, by which time it is assigned. It
  // also translates the router's camelCase RouteView into the FIELD NAMES of `Osyrin.NavigationRoute`, which is what a
  // render expression (`r.Title`) actually reads. Absent without a router: `Navigation` is then an unbound name.
  let router: Router | undefined;
  const navigation: NavigationHost = {
    routes: () => (router?.routes ?? []).map((r) => ({
      Path: r.path, Title: r.title, IsActive: r.isActive, IsDirty: r.isDirty,
    })),
    currentPath: () => router?.currentPath ?? null,
    isCurrentDirty: () => router?.currentDirty ?? false,
    onChange: (cb) => router?.onChange(cb) ?? (() => {}),
    // Fire-and-forget: navigation mounts a page, and an action body must not block on the next route's data.
    go: (path) => { void router?.navigate(path); },
    close: (path, force) => router?.closeRoute(path, { force }) ?? false,
    // D57/D71 — commit the route's own overlay, then close it. The promise is RETURNED, not dropped: the commit can be
    // refused, and `Navigation.Save` now awaits it so the app's prompt can catch that and say why. `void`-ing it here
    // was the last link in the chain that swallowed a refused save.
    save: (path) => router ? router.saveRoute(path).then(() => undefined) : Promise.resolve(),
    // D85 — the target route's `derived canSave` guard, for `Navigation.CanSave(path)`. The shell gates its close-prompt
    // Save option on it; defaults to true (nothing forbids saving) with no router or for a guardless page.
    canSave: (path) => router?.canSaveRoute(path) ?? true,
  };

  // Fetch + mount a component into `container`. An SSR route already painted its tree, so `hydrate` adopts it.
  // The route's captured params ride the TREE fetch (D53-e): they are what lets the server BIND a param-bound
  // predicate (`o.Slug == slug`) and return its rows in the same response. Without them a page like /org/{slug} could
  // not be pre-resolved at all, and paid a second round trip for its data.
  const mount = (component: string, params: Record<string, string>, container: Element, hydrate: boolean) =>
    session.componentSource.fetch(component, params).then((tree) => mountComponent(tree, container, {
      props: params,
      source: session.componentSource,
      // `navigation` only when a router exists — a bare mount has no routes, so reading `Navigation` should be the
      // loud unbound-name error, not a silently empty list.
      data: router ? { ...session.renderData, navigation } : session.renderData,
      controls: session.controlSource,   // P2e — foreign controls load their package from /_osy/control/{hash}
      controlData: session.controlDataScope,   // host.data — a control that owns its data surface reads/writes app paths
      hydrate,
    }));

  // D23 Phase 1b/2b — take over navigation. From here an in-app link swaps the page in place: no reload, real
  // addresses, working back/forward; and a page inside a `[Layout]` keeps that layout mounted across navigations.
  // Skipped when the shell shipped no route manifest or there's no browser (a node/SSR host) — then we mount plainly.
  const routes = descriptor.routes ?? [];
  const env = opts.routerEnv === undefined ? browserRouterEnv() : opts.routerEnv ?? undefined;
  const hydrate = host.childNodes.length > 0;

  // `window.__osy` (plan I1). Installed BEFORE the mount, and outside the try, for two reasons: the handle reads its
  // root LAZILY (the router mounts below), and a boot that FAILS is exactly when you most want to inspect — the net
  // ring already holds the request that 500'd. A non-dev host installs nothing at all.
  let rootRef: ComponentInstance | null = null;
  /** ⭐ THE COMPONENT TREES THAT ARE ON SCREEN RIGHT NOW — the layout and the ACTIVE route, asked of the router on
   *  every call rather than captured once.
   *
   *  ⛔ `rootRef` IS THE BOOT-TIME PAGE AND NOTHING KEEPS IT CURRENT. The router swaps the outlet's child on every
   *  in-app navigation and disposes the old instance; `rootRef` still names that disposed instance, which answers
   *  0 / empty to everything — indistinguishable from a live, quiet page. So every reader below was describing the
   *  wrong screen after the first navigation, and none of them could say so. See `Router.liveInstances` for the
   *  measurement that found it.
   *
   *  Falls back to `rootRef` for a BARE mount (no router at all), which is the one case where the boot-time
   *  instance really is the whole screen for the life of the document. */
  const onScreen = (): readonly ComponentInstance[] =>
    router ? router.liveInstances : (rootRef ? [rootRef] : []);
  const sum = (read: (i: ComponentInstance) => number): number => {
    let total = 0;
    for (const i of onScreen()) total += read(i);
    return total;
  };
  const devSources = {
    appSlug: descriptor.appSlug ?? null,
    component: descriptor.component ?? null,
    devHost,
    net: netRing,
    // The log ring lives on the SESSION (it is a sink on the logger), so it is read through, not copied.
    // Rendered through the SAME template renderer the console and the server sinks use, so a line reads identically
    // wherever you look at it.
    getLogs: () => session.logRing.all().map((e) => ({
      level: e.level,
      message: renderLogTemplate(e.template, e.fields),
      at: Date.now(),
      correlationId: e.correlationId ?? null,
    })),
    clearLogs: () => session.logRing.clear(),
    getRoot: () => { const live = onScreen(); return live[live.length - 1] ?? rootRef; },
    getRouter: () => router ?? null,
    getStore: () => (session as unknown as { store?: never }).store ?? null,
  };
  // The panel renders `buildProbe(devSources)` — the SAME call `dump()` makes. That is the sync guarantee: there is
  // one definition of the app's runtime state, and the human view and the machine view are two renderers over it.
  // Is the app BUSY? — how many action interactions are in flight, for a host that must not act mid-interaction
  // (a headless driver waiting for a click to finish). Deliberately NOT on the dev handle: `__osy` is gated on
  // `traceEnabled`, so a consumer built on it works against a dev server and silently degrades everywhere else,
  // which is the worst possible split. This answers on every host because being busy is not a debug fact.
  opts.onActivity?.(() => sum((i) => i.inFlightActions));
  opts.onActionsStarted?.(() => sum((i) => i.startedActions));
  opts.onDialogAwaits?.(() => sum((i) => i.dialogAwaits));
  opts.onNavActivity?.(() => router?.navsInFlight ?? 0);
  opts.onRenderPending?.(() => liveListFlushesPending());
  opts.onValidation?.(() => onScreen().flatMap((i) => [...i.revealedViolations]));
  // M199 — what each mounted control says about ITSELF. Same shape and same reasoning as the two above: a reader,
  // ungated, late-bound through the ROUTER because the router mounts after boot AND swaps the page on every
  // navigation — see `onScreen`.
  opts.onControlProbes?.(() => onScreen().flatMap((i) => i.controlProbeReadings()));
  // Is any part of the page still showing its `skeleton { }`? Ungated for the same reason as the readers above:
  // being mid-load is not a debug fact, and a headless reader cannot tell a skeleton from an empty page.
  opts.onSkeletons?.(() => sum((i) => i.skeletonsShowing()));
  opts.onLeaving?.(() => isNavigating());
  opts.onBooted?.(() => firstMountDone);

  const devPanel = devHost ? installDevPanel(() => buildProbe(devSources), doc) : null;
  installDevHandle(devSources, undefined, () => devPanel?.open());

  // ⚠ REGISTERED AGAINST THE HOST, NOT AGAINST THE RETURNED PAGE — and the difference is a bug the suite caught.
  // Hanging this off the mounted instance reads naturally and is wrong: on the router path that instance is the
  // CURRENT PAGE, which the router disposes on every navigation. So the first in-app click tore down the very router
  // that was handling it ("navigation failed: Cannot read properties of null (reading 'replaceChildren')"). A boot's
  // lifetime is the HOST's, which is also what `bootsInFlight` is keyed by.
  bootTeardowns.set(host, () => {
    if (router) { const r = router; router = undefined; r.dispose(); }
    connection.stop();
    for (const t of teardowns) t();
    teardowns.length = 0;
    // [[M174]] — LAST, and after the router has disposed the page. The socket is what outlives everything else: the
    // router stops listening and the monitor stops pinging, but a live transport keeps its subscriptions, keeps
    // receiving frames, and RECONNECTS when the socket drops. So a disposed boot used to leave a ghost that a later
    // boot's `/live` could see re-subscribing beside it. Closed after the page so nothing still mounted reads a
    // session whose realtime has gone.
    session.closeRealtime();
  });

  try {
    if (routes.length > 0 && env) {
      router = new Router({
        routes,
        host,
        env,
        doc,
        mount,
        // Warm the next route's tree while the current page is still on screen (the source memoizes, so `mount`
        // reuses this fetch rather than repeating it).
        prefetch: (component, params) => session.componentSource.fetch(component, params),
        // D118 — a navigation uses the SAME busy timing as a control's action spinner, so the app has one answer to
        // "how long before we admit we're waiting" rather than two.
        pendingDelayMs: descriptor.pendingDelayMs ?? 0,
        pendingMinShowMs: descriptor.pendingMinShowMs ?? 0,
        // A stored token means the visitor logged in; an anonymous launch token does not. The server is the real gate —
        // this only spares a doomed fetch and lands the user on the login page instead of a 403.
        isAuthenticated: () => readStoredToken() != null,
        onAuthRequired: (path) => (opts.redirect ?? defaultRedirect)(
          withReturnTo(opts.loginRoute ?? descriptor.loginRoute ?? '/login', path)),
        // A navigation whose page-tree fetch 403s is the server answering "this account can't see this page" — NOT a
        // server-loss. The router's mount-rollback keeps the current screen intact, but stopping there is a SILENT
        // no-op (the URL moved, the content didn't, and the user is told nothing). Route it to the SAME access-denied
        // surface the boot/direct-nav path shows (the app's ForbiddenSurface, else the built-in). Any other error (a
        // genuine transport reject) stays a log — the connection monitor owns the reconnecting overlay.
        onError: (err) => {
          if (err instanceof OsyHttpError && err.status === 403) {
            void handleBootFailure(host, err, onUnauthorized, descriptor, bootSurfaces);
            return;
          }
          console.error('[osy] navigation failed', err);
        },
      });
      opts.onRouter?.(router);

      // D75 — the app was RECOMPILED. The server has always broadcast `metadata_changed` to every connected browser;
      // the client dropped it on the floor, so an open page kept rendering the OLD component trees and enforcing the
      // OLD validation rules until someone hard-reloaded. Now it refreshes IN PLACE: the session drops its cached trees
      // and re-reads the model, and the router re-mounts the routes it safely can.
      //
      // The session is untouched — same token, same context, no re-login. And a DIRTY route is left strictly alone: its
      // overlay is the user's unsaved work, and a dev-loop convenience is not a reason to destroy an edit.
      teardowns.push(session.onMetadataChanged(() => {
        void (async () => {
          try {
            await session.refreshMetadata();
            const { remounted, skippedDirty, staleManifest } = await router!.refreshRoutes();
            if (skippedDirty > 0)
              console.info(`[osy] the app was recompiled — ${remounted} route(s) refreshed; ${skippedDirty} left alone `
                + 'because they hold unsaved edits (save or discard them to pick up the new version).');
            // The recompile changed the ROUTING SURFACE, which a live page cannot follow: the route manifest is served
            // inside the shell HTML and has no runtime source to re-read, so this tab goes on matching against the one
            // it booted with. Said out loud because the alternative is what it did before — leave the reader looking at
            // the old build of the page they are on, after a compile that appeared to succeed, with nothing anywhere
            // explaining it.
            if (staleManifest > 0)
              console.warn(`[osy] the app was recompiled and ${staleManifest} open route(s) are no longer in the route `
                + 'manifest this tab booted with — RELOAD to pick up the new routing surface. Until then those pages '
                + 'are the previous build.');
          } catch (err) {
            // Never let a refresh failure take the page down: the user keeps the app they have, and says so out loud.
            console.error('[osy] the app was recompiled but the refresh failed — reload to pick up the new version.', err);
          }
        })();
      }));

      // The router owns the FIRST mount too, so the server-resolved route gets its layout exactly as a later
      // navigation would. Component names are unique, so the manifest entry is the descriptor's own route.
      const entry = routes.find((r) => r.component === descriptor.component)
        ?? { route: '/', component: descriptor.component, requiresAuth: descriptor.requiresAuth };
      // Register the mount under the path this boot RESOLVED the component from — `bootMatch` above matched
      // `bootPath` to pick `descriptor.component`, so anything else here would file the route under a path that
      // names a different page. The query string is dropped because a route identity is its path (`env.path()` is
      // `location.pathname`, and the retained-tab key must not vary with `?returnTo=…`).
      rootRef = await router.startAt(entry, descriptor.params, hydrate, bootPath.split('?')[0] || '/');
      // ⛔ ONLY WHEN SOMETHING ACTUALLY MOUNTED. `startAt` answers NULL when the route's auth gate refuses — it
      //    mounts nothing and fires the login redirect instead, so the page is NAVIGATING, not booted. Setting the
      //    latch there told a waiting driver "the app has rendered" about a document that never would: the server's
      //    shell was on screen, the outlet was empty, and the redirect had not landed yet.
      //
      // ⚑ MEASURED 2026-09-01 under load: a signed-in test read "(nothing rendered)" after 64 seconds of waiting,
      //    because the wait it was blocked on had already been satisfied by a boot that mounted nothing. Leaving
      //    the latch false is correct AND safe — a refusal is always followed by a navigation, and the next
      //    document boots and mounts, which is what the waiter is actually waiting for.
      if (rootRef !== null) firstMountDone = true;
      return rootRef;
    }

    rootRef = await mount(descriptor.component, descriptor.params, host, hydrate);
    firstMountDone = true;
    return rootRef;
  } catch (err) {
    // The FIRST mount fetched the page tree; if that failed, show a readable surface instead of a blank page + a
    // console trace. An anonymous visitor to a protected route was already redirected pre-fetch (the router gate), so
    // a 401/403 here is an authenticated caller: 401 = stale ticket (re-login), 403 = not permitted (a clear message).
    return await handleBootFailure(host, err, onUnauthorized, descriptor, bootSurfaces);
  }
}

/** The app's inlined boot-failure surfaces (app.Ui.ForbiddenSurface / ErrorSurface), in hand at boot. Null when the app
 *  declared none → the built-in surface. */
interface BootSurfaces {
  forbidden: ComponentTree | null;
  error: ComponentTree | null;
}

/** Mount an inlined app surface into the host, replacing whatever a failed mount left there. Self-contained by
 *  construction (built-in atoms + bundled [Composable] children, no data), so it needs no session — which is the whole
 *  point: it renders even when the failure happened before a session opened. Returns true on success; false lets the
 *  caller fall back to the built-in surface (a malformed tree must never leave a blank page). */
async function mountBootSurface(host: Element, tree: ComponentTree): Promise<boolean> {
  try {
    host.replaceChildren();
    await mountComponent(tree, host, {});
    return true;
  } catch (err) {
    console.error('[osy] failed to mount the app boot-failure surface — falling back to the built-in', err);
    return false;
  }
}

async function handleBootFailure(
  host: Element, err: unknown, onUnauthorized: () => void, descriptor: BootDescriptor, surfaces: BootSurfaces,
): Promise<null> {
  const loginRoute = descriptor.loginRoute ?? '/login';
  if (err instanceof OsyHttpError && err.status === 401) {
    onUnauthorized();                                      // the ticket is stale — drop it + re-login (guarded once)
    return null;
  }
  if (err instanceof OsyHttpError && err.status === 403) {
    // The app owns the forbidden surface? Mount its inlined tree. Else the built-in access-denied surface.
    if (surfaces.forbidden && await mountBootSurface(host, surfaces.forbidden)) return null;
    renderBootError(host, {
      title: "You don't have access to this page",
      message: "You're signed in, but this account isn't permitted to view this page. Sign in with an account that has access, or go to your home page.",
      detail: err.detail,                                  // the server's reason — verbose on the dev server, terse in prod
      // A 403 means THIS account can't see the page — so the FIRST escape is to sign in as a different account (the
      // login route drops the current session, so it's a clean re-auth: this is how a user holding the WRONG account's
      // session gets to the right one). Home (`/`) is the secondary escape for an account that legitimately just lacks
      // this one page. Without either, a 403 replaces the whole app and strands the user with no navigation.
      links: [
        { label: 'Sign in with a different account', href: loginRoute },
        { label: 'Go to your home page', href: '/' },
      ],
    });
    return null;
  }
  console.error('[osy] boot failed', err);
  // The app owns the error surface? Mount its inlined tree. Else the built-in "couldn't load" surface.
  if (surfaces.error && await mountBootSurface(host, surfaces.error)) return null;
  renderBootError(host, {
    title: "This page couldn't load",
    message: 'Something went wrong while loading this page.',
    detail: err instanceof Error ? err.message : String(err),
    links: [{ label: 'Go to your home page', href: '/' }],
  });
  return null;
}

// ── the app-authored connection-loss surface (slice 3c) ──────────────────────────────────
// When the app declared `app.Ui.ConnectionSurface`, the boot descriptor names that component. Pre-fetch its tree while
// the server is alive (a drop is exactly when we could not fetch it), then install a renderer on the monitor that
// mounts the tree — bound to the `Connection` ambient — as a fixed overlay on a drop and tears it down on recovery.
// The surface renders CLIENT-side with no further server calls, so it must be self-contained (built-in elements only,
// no child ComponentRefs and no uncached foreign controls) — anything it would fetch is unreachable once the server
// is gone. A no-op when the app declared none: the built-in default overlay stays.

/** The ConnState string → enum ordinal the surface's `switch (Connection.State)` compares against (Ok=0 etc.). */
const CONN_STATE_ORDINAL: Record<ConnState, number> = { ok: 0, reconnecting: 1, lost: 2 };

async function wireConnectionSurface(
  descriptor: BootDescriptor,
  session: PlatformSession,
  connection: ConnectionMonitor,
  opts: BootOptions,
  doc: Document,
): Promise<void> {
  const name = descriptor.connectionSurface;
  if (!name) return;   // app declared no surface → the built-in default overlay stays

  // Pre-fetch NOW (the server is alive). Non-fatal on failure: leave the default overlay in place.
  let tree;
  try { tree = await session.componentSource.fetch(name, {}); }
  catch { return; }

  // The `Connection` ambient, backed by the monitor's live state.
  let curState: ConnState = 'ok';
  let curAttempts = 0;
  const listeners = new Set<() => void>();
  const host: ConnectionHost = {
    state: () => CONN_STATE_ORDINAL[curState],
    attempts: () => curAttempts,
    onChange: (cb) => { listeners.add(cb); return () => { listeners.delete(cb); }; },
    retry: () => connection.retry(),
    reload: () => {
      if (opts.redirect) opts.redirect(defaultCurrentPath() || '/');
      else (globalThis as { location?: { reload(): void } }).location?.reload();
    },
  };

  const ID = 'osy-connection-surface';
  let container: HTMLElement | null = null;
  let instance: ComponentInstance | null = null;
  let mounting = false;

  const teardown = () => {
    instance?.dispose();
    container?.remove();
    instance = null; container = null;
  };

  connection.setRender((state, ctx) => {
    curState = state;
    curAttempts = ctx.attempts;
    // Reactive update of an already-mounted surface: bump every subscribed slot (connectionView reads via connSignal).
    for (const cb of [...listeners]) cb();

    if (state === 'ok') { teardown(); return; }
    if (container || mounting) return;   // already shown (or mounting) — the reactive update above handled the change
    mounting = true;
    container = doc.createElement('div');
    container.id = ID;
    // A bare mount node — the app's surface element owns ALL positioning (a `Position=Fixed` curtain for `lost`, a
    // top-anchored strip for `reconnecting`), so the surface decides whether it blocks the intact rolled-back view
    // underneath. The container itself is a 0-size node; the fixed child positions against the viewport.
    doc.body.appendChild(container);
    void mountComponent(tree, container, {
      props: {},
      source: session.componentSource,
      data: { ...session.renderData, connection: host },
      controls: session.controlSource,
      controlData: session.controlDataScope,
      hydrate: false,
    }).then((inst) => {
      mounting = false;
      if (curState === 'ok') { inst.dispose(); teardown(); return; }   // recovered while mounting — tear straight down
      instance = inst;
    }).catch(() => { mounting = false; });
  });
}

// ── default token acquisition (browser) ──────────────────────────────────────────────────
// A stored app token (from a prior login) wins; otherwise launch anonymously (POST /api/launch-anonymous). An app
// with no anonymous surface returns 403 → null, which routes an [Authorize] page to login above.

const STORED_TOKEN_KEY = 'osy.appToken';

function defaultGetToken(opts: BootOptions): (d: BootDescriptor) => Promise<string | null> {
  return async () => {
    const stored = readStoredToken();
    if (stored) return stored;

    const http = opts.fetch ?? fromGlobalFetch();
    // ⛔ RETRY A THROWN NETWORK ERROR ONCE — this is the FIRST request the page makes, and on a freshly served app
    //   it is aborted often enough to be reproducible. MEASURED 2026-08-27 against an eval workspace in real
    //   Chromium: on the FIRST load of a newly served app the browser reports `POST /api/launch-anonymous` as
    //   net::ERR_ABORTED and the fetch throws `Failed to fetch`, while the SERVER logs the same request answered
    //   200 in 6.3ms. Every reload after it is clean. The page recovered and was fully interactive — so what the
    //   user actually got was a console error on a working app, and what WE got was a "the console is clean"
    //   check that is red on every healthy app and therefore worth nothing.
    // ⚠ ONLY A THROW, never a non-ok RESPONSE. A 403 is the server ANSWERING "this app has no anonymous surface",
    //   which routes an [Authorize] page to login below; retrying an answer would turn a normal path into a
    //   double request on every locked-down app. A throw is the absence of an answer, which is the only thing a
    //   retry can help with — and a second failure still surfaces, so this hides nothing.
    let res: HttpResponse;
    try {
      res = await http(`${opts.baseUrl ?? ''}/api/launch-anonymous`, { method: 'POST' });
    } catch {
      res = await http(`${opts.baseUrl ?? ''}/api/launch-anonymous`, { method: 'POST' });
    }
    if (!res.ok) return null;
    // The server's LaunchResponse ships the token as `applicationToken` (camelCased ApplicationToken).
    const body = (await res.json()) as { applicationToken?: string };
    return body.applicationToken ?? null;
  };
}

// ── default live-data transport (browser) ────────────────────────────────────────────────
// Built only for an app-scoped token in a browser with a WebSocket + location. The `?token=` auth is the server's
// contract (a WS upgrade can't carry an Authorization header); the server re-validates and enforces scope.

function defaultWs(token: string, liveReload: boolean, onGiveUp?: () => void): WsTransport | undefined {
  const hasWebSocket = typeof (globalThis as { WebSocket?: unknown }).WebSocket === 'function';
  const url = hasWebSocket ? wsUrl(token) : null;
  // An app-scoped token always gets the WS (live queries + metadata_changed). An ANON token gets one only when
  // `liveReload` says this is the local dev server — the only host that accepts an anon WS — so an anon page can
  // hot-reload on recompile. Elsewhere an anon page has no `live query` and the server would 403 the connection.
  if (!url || (jwtScope(token) !== 'application' && !liveReload)) return undefined;
  // `onGiveUp` fires when the upgrade is refused over and over — in practice an EXPIRED token, since the server 401s
  // the handshake and a browser hides that status from script. Route it to the same re-auth path a 401 on any other
  // request takes: without it the page keeps rendering, silently never receives another live update, and the tab
  // reconnects every 15s forever against a session that cannot come back.
  return browserWsTransport(url, { onGiveUp });
}

/** Derive the /api/ws URL from the page origin (ws↔http, wss↔https), carrying the token as a query param.
 *  Returns null outside a browser (no location). */
export function wsUrl(token: string): string | null {
  const loc = (globalThis as { location?: { protocol: string; host: string } }).location;
  if (!loc?.host) return null;
  const scheme = loc.protocol === 'https:' ? 'wss:' : 'ws:';
  return `${scheme}//${loc.host}/api/ws?token=${encodeURIComponent(token)}`;
}

function readStoredToken(): string | null {
  const storage = (globalThis as { sessionStorage?: { getItem(k: string): string | null } }).sessionStorage;
  try {
    return storage?.getItem(STORED_TOKEN_KEY) ?? null;
  } catch {
    return null;
  }
}

// ── the Session.SignIn(ticket) effect (auth login→elevate) ─────────────────────────────────
// Store the server-issued ticket as the app token, then navigate to the return-to (the page the user was sent to
// login FROM) — a full navigation RE-BOOTS, and the fresh boot reads the stored token → mounts authenticated. The
// ticket is a pure courier: stored verbatim, no client-side verification (the server re-verifies every request).

function makeSignIn(opts: BootOptions, descriptor?: BootDescriptor): (ticket: unknown) => void {
  return (ticket) => {
    // An [AuthMethod] returns a signed ticket on success or "" on failure (a wrong password / taken email). An EMPTY
    // ticket is NOT a login — storing it (an empty bearer) and navigating dumped the user on the authed landing page,
    // which then 403'd into a dead-end "no access" with no hint that the PASSWORD was simply wrong. So a falsy ticket
    // is a no-op: nothing stored, no navigation — the caller stays on the login page and can show a credentials error.
    const t = ticket == null ? '' : String(ticket);
    if (t === '') return;
    writeStoredToken(t);
    // NEVER return to the login page itself. A `returnTo` pointing at `/login` sends the freshly-authenticated user
    // straight back to the form — and boot's "arrived at the login route holding a token" rule then CLEARS the token
    // they just earned, so a correct password looks like a failed one. That is what the nesting-loop URLs in the wild
    // do, and this arm is what makes an already-broken URL (a bookmark, an open tab) heal itself instead of trapping
    // whoever opens it. `isSameRoute` ignores the query, which is the whole point: the bad values ARE all query.
    const loginRoute = opts.loginRoute ?? descriptor?.loginRoute ?? '/login';
    const back = readReturnTo();
    // The navigation below aborts this action's own in-flight requests. Say so, or the successful sign-in that
    // caused it is reported as a failed action (see `navigating.ts`).
    markNavigating();
    (opts.redirect ?? defaultRedirect)(back && !isSameRoute(back, loginRoute) ? back : '/');
  };
}

// ── the Session.SignOut() effect (auth logout) ──────────────────────────────────────────────
// The mirror of makeSignIn: DROP the stored ticket, then navigate to the login route — a full navigation RE-BOOTS, and
// the fresh boot finds no token → mounts anonymous. There is no server round trip: the token lives in the browser and
// the server keeps no session to invalidate (every request re-verifies the bearer, and a dropped bearer is anonymous).
function makeSignOut(opts: BootOptions, descriptor: BootDescriptor): () => void {
  return () => {
    clearStoredToken();
    const route = opts.loginRoute ?? descriptor.loginRoute ?? '/login';
    markNavigating();
    (opts.redirect ?? defaultRedirect)(route);
  };
}

function writeStoredToken(token: string): void {
  const storage = (globalThis as { sessionStorage?: { setItem(k: string, v: string): void } }).sessionStorage;
  try { storage?.setItem(STORED_TOKEN_KEY, token); } catch { /* storage unavailable — the session bearer still worked for this load */ }
}

/** OAuth login handoff. The `/api/oauth/callback` endpoint redirects the browser back to the app with the signed app
 *  ticket as an `oauth_token` param (in the query or the fragment). If present, store it as the app token (this boot
 *  then mounts authenticated) and STRIP it — plus its `user_id`/`is_new_user` siblings — from the URL via
 *  `history.replaceState`, so the ticket is never left in the address bar, history, or a referrer. A no-op when there
 *  is no such param (every ordinary boot). */
export function consumeOAuthCallbackToken(opts: BootOptions = {}): void {
  const loc = (globalThis as { location?: { href: string; search: string; hash: string } }).location;
  const hist = (globalThis as { history?: { replaceState(d: unknown, t: string, u: string): void } }).history;
  if (!loc) return;
  const inQuery = new URLSearchParams(loc.search);
  const inFrag = loc.hash.startsWith('#') ? new URLSearchParams(loc.hash.slice(1)) : new URLSearchParams();
  const token = inQuery.get('oauth_token') ?? inFrag.get('oauth_token');
  if (!token) return;

  writeStoredToken(token);
  for (const p of ['oauth_token', 'user_id', 'is_new_user']) { inQuery.delete(p); inFrag.delete(p); }
  const q = inQuery.toString();
  const f = inFrag.toString();
  const path = (opts.currentPath ?? defaultCurrentPath());
  const clean = path.split('?')[0].split('#')[0] + (q ? '?' + q : '') + (f ? '#' + f : '');
  try { hist?.replaceState(null, '', clean); } catch { /* history unavailable — the token is stored either way */ }
}

/** Drop the stored ticket — a stale/invalid one (a 401) must not be reused; the next boot launches anonymous again. */
function clearStoredToken(): void {
  const storage = (globalThis as { sessionStorage?: { removeItem(k: string): void } }).sessionStorage;
  try { storage?.removeItem(STORED_TOKEN_KEY); } catch { /* storage unavailable */ }
}

/** The response to a 401 on an authed request: the stored ticket is stale, so drop it and send the user to log in,
 *  carrying a return-to so they land back where they were. Returns a GUARDED callback — a page issues many authed
 *  requests at boot, and a stale ticket 401s all of them; without the guard each would fire its own redirect. */
function makeUnauthorizedHandler(opts: BootOptions, descriptor: BootDescriptor): () => void {
  let redirected = false;
  return () => {
    if (redirected) return;
    redirected = true;
    clearStoredToken();
    const route = opts.loginRoute ?? descriptor.loginRoute ?? '/login';
    const here = opts.currentPath ?? defaultCurrentPath();
    // Never bounce the login page to itself — its own fetches are anonymous and shouldn't 401, but a loop would be
    // worse than doing nothing.
    // ⚑ This compared `here === route` and so NEVER FIRED: `here` is `defaultCurrentPath()`, which is pathname PLUS
    // QUERY, while `route` is a bare path — so on `/login?returnTo=X` the test was `"/login?returnTo=X" === "/login"`,
    // false. Each 401 then wrapped the whole current URL into a fresh `returnTo`, re-encoding the previous one every
    // round (%2F -> %252F -> %25252F), and once a login finally succeeded it sent the user back to the LOGIN page —
    // where boot's own "arrived at login holding a token" rule cleared the token they had just earned. Reported as
    // "a few failed logins and now it won't navigate to the start page". `isSameRoute` is the comparison this always
    // wanted: it is defined in this file and already used for the same question at boot.
    if (isSameRoute(here, route)) return;
    (opts.redirect ?? defaultRedirect)(withReturnTo(route, here));
  };
}

/** Wrap a fetch so any 401 fires `onUnauthorized`. THE chokepoint: it sits at the transport, so it catches a stale
 *  ticket uniformly — the boot `POST /api/context` (which today throws a plain Error, not a classifiable OsyHttpError,
 *  and escapes boot's own try/catch), every `/query` and `/ui` and `/fn/*`, and an upload. The response is still
 *  returned so the caller's normal error path runs; by then the redirect is already under way. */
function interceptUnauthorized(base: HttpFetch, onUnauthorized: () => void): HttpFetch {
  return async (url, init) => {
    const res = await base(url, init);
    if (res.status === 401) onUnauthorized();
    return res;
  };
}

/** The `?returnTo=` the login redirect carried (the protected page to come back to), or null.
 *
 *  SECURITY-INVARIANT(return-to-is-a-local-path): this value is ATTACKER-CONTROLLED — it is read straight out of the
 *  query string of a URL anyone can hand you — and it is passed to `location.assign()` the instant a login SUCCEEDS.
 *  So it must be a path on THIS origin and nothing else. Without the filter, `…/login?returnTo=https://evil.example/`
 *  is an OPEN REDIRECT that fires at the highest-trust moment in the app: the user has just typed their password, the
 *  app said yes, and the browser lands them on a page the attacker controls — the setup for a "session expired, sign
 *  in again" clone. Rejected, and each matters: an absolute URL, a PROTOCOL-RELATIVE one (`//evil`, which
 *  `location.assign` treats as another origin), the backslash forms some browsers normalize to `//`, any scheme
 *  (`javascript:`, `data:`), and control characters that can smuggle one past a naive check. A rejected value reads as
 *  ABSENT, so login falls back to `/`. Guarded by `tests/boot/boot-return-to.test.ts`. */
function readReturnTo(): string | null {
  const loc = (globalThis as { location?: { search?: string } }).location;
  const m = loc?.search ? /[?&]returnTo=([^&]+)/.exec(loc.search) : null;
  return m ? safeReturnTo(decodeURIComponent(m[1])) : null;
}

/** The local-path filter behind SECURITY-INVARIANT(return-to-is-a-local-path). Exported for its test. */
export function safeReturnTo(value: string | null | undefined): string | null {
  if (!value) return null;
  // Exactly one leading '/' is the only shape that cannot leave this origin; '//' and '/\\' are protocol-relative.
  if (value[0] !== '/') return null;
  if (value[1] === '/' || value[1] === '\\') return null;
  // CONTROL characters only. An earlier spelling of this was `[ -]` — "space or hyphen" — which would have rejected
  // every ordinary path carrying a slug (`/org/acme/apps/crm-acme/settings`), i.e. the whole app.
  if (/[\x00-\x1F\x7F]/.test(value)) return null;
  return value;
}

function defaultRedirect(url: string): void {
  const loc = (globalThis as { location?: { assign(u: string): void } }).location;
  loc?.assign(url);
}

// The current path (+ query) to return to after login. Empty at the app root or outside a browser (no return-to).
function defaultCurrentPath(): string {
  const loc = (globalThis as { location?: { pathname?: string; search?: string } }).location;
  const path = (loc?.pathname ?? '') + (loc?.search ?? '');
  return path === '/' ? '' : path;
}

/** Two routes are the same page when their PATHS match, ignoring any query string and a trailing slash. Used to tell
 *  whether this boot is on the app's declared login route (a static path). `defaultCurrentPath` returns '' for the root,
 *  so normalize that to '/' on both sides. */
function isSameRoute(a: string, b: string): boolean {
  const norm = (s: string) => (s.split('?')[0].replace(/\/+$/, '') || '/');
  return norm(a) === norm(b);
}

/** Append `?returnTo=<path>` to the login route (correctly joining an existing query), or the bare route when there's
 *  nothing to return to (the app root). */
export function withReturnTo(route: string, returnTo: string): string {
  if (!returnTo) return route;
  const sep = route.includes('?') ? '&' : '?';
  return `${route}${sep}returnTo=${encodeURIComponent(returnTo)}`;
}

export { jwtScope };
