// Locale slice 1b — the app's DECLARED cultures' format plans, projected out of the AMM the server serves at
// `GET /api/metadata` (the enum-map precedent, model-enums.ts). A culture-format call ships as a `cultureFormatStd` /
// `cultureFormatPlan` node carrying only the BCP-47 TOKEN (the plan is large and shared across call sites, ledger L17);
// the interpreter and the render evaluator look the token's plan up HERE. The token was proved DECLARED at compile
// time, so its plan is always present — a miss is a wiring bug (the model didn't load), surfaced loudly, never a
// silent wrong number.

import type { CultureFormatDto, MetadataModelDto } from './model-dto.js';
import { INVARIANT_NUMBER_PLAN, type CultureNumberPlan } from '../runtime/stdlib.js';
import { INVARIANT_DATE_PLAN, type CultureDatePlan } from '../runtime/date-format.js';

/** BCP-47 token → the culture's numeric format plan. */
export type CultureStore = Record<string, CultureFormatDto>;

export const EMPTY_CULTURES: CultureStore = {};

/** Project the served cultures into a token-keyed store. */
export function projectCultures(model: MetadataModelDto): CultureStore {
  const store: CultureStore = {};
  for (const c of model.cultures ?? []) store[c.culture] = c;
  return store;
}

/** The numeric plan for a declared culture token. Throws if the token is absent — it was compile-validated as
 *  declared, so a miss means the app's model did not load (a wiring bug), which must fail loudly, not format wrongly.
 *  The empty token is the invariant culture (the app-default path when no explicit culture is given). */
export function culturePlan(store: CultureStore, token: string): CultureNumberPlan {
  if (token === '') return INVARIANT_NUMBER_PLAN;
  return lookup(store, token).number;
}

/** The DATE plan for a declared culture token (locale slice 1b-5). The empty token is the invariant culture (CR-1 /
 *  GAP 1) — a culture-LESS date format (`$"{date:d}"`, shipped as a `dateFormat` node) renders through
 *  INVARIANT_DATE_PLAN, byte-identically to the server's InvariantCulture. A non-empty token was compile-validated as
 *  declared, so a miss means the model didn't load (a wiring bug) and fails loudly. */
export function cultureDatePlan(store: CultureStore, token: string): CultureDatePlan {
  if (token === '') return INVARIANT_DATE_PLAN;
  return lookup(store, token).date;
}

function lookup(store: CultureStore, token: string): CultureFormatDto {
  const c = store[token];
  if (!c) throw new Error(`culture '${token}' has no format plan — the app's model wasn't loaded (cultures channel).`);
  return c;
}
