// Reading the client's own token. Its own module rather than a corner of `boot.ts` because the SESSION needs it too
// — and session.ts cannot import boot.ts, which imports session.ts.

/** Read the (unverified) `scope` claim from a JWT's payload — a client-side gate only (the server verifies the
 *  signature + re-checks scope). Returns null for a malformed token. */
export function jwtScope(token: string): string | null {
  const parts = token.split('.');
  if (parts.length !== 3) return null;
  try {
    const payload = base64UrlDecode(parts[1]);
    const claims = JSON.parse(payload) as { scope?: unknown };
    return typeof claims.scope === 'string' ? claims.scope : null;
  } catch {
    return null;
  }
}

function base64UrlDecode(segment: string): string {
  const b64 = segment.replace(/-/g, '+').replace(/_/g, '/');
  const g = globalThis as { atob?: (s: string) => string; Buffer?: { from(s: string, enc: string): { toString(enc: string): string } } };
  if (typeof g.atob === 'function') return g.atob(b64);
  if (g.Buffer) return g.Buffer.from(b64, 'base64').toString('binary'); // node (tests)
  throw new Error('no base64 decoder available');
}
