// Server-loss handling. When the server drops mid-session, requests stop resolving; the router already ROLLS BACK a
// failed navigation (no teardown), and THIS is the surface that tells the user what happened and lets them recover.
//
// The monitor is a small state machine fed by the transport: every request reports up/down. A network reject or a
// gateway status (>= 502 — the server is down/restarting, NOT a 500 app error) flips it to `reconnecting`; it then
// pings a cheap always-served asset with backoff, escalating to `lost` after a few misses, and returns to `ok` the
// moment a ping (or any real request) succeeds. A 401 is NOT connection loss — the caller's existing handler redirects
// to login. This file ships a plain DEFAULT overlay; an app replaces it with its own (app.Ui.ConnectionSurface, next
// slice) by supplying a `render` hook.

import type { HttpFetch } from './http.js';

export type ConnState = 'ok' | 'reconnecting' | 'lost';

/** Wrap a transport so every request reports up/down to the monitor — THE chokepoint, like interceptUnauthorized. A
 *  resolved response (any status) is classified; a reject is reported down and re-thrown so the caller's error path
 *  still runs (the router rolls the navigation back). */
export function monitorConnection(base: HttpFetch, monitor: ConnectionMonitor): HttpFetch {
  return async (url, init) => {
    let res;
    try { res = await base(url, init); }
    catch (err) { monitor.report(classifyStatus(null, true)); throw err; }
    monitor.report(classifyStatus(res.status, false));
    return res;
  };
}

/** A request outcome only matters as up/down/neither: a reject or a gateway status is DOWN; any other RESPONSE (even a
 *  401/404/500 — the server answered) is UP. `null` = don't touch the state (e.g. a request we chose not to monitor). */
export function classifyStatus(status: number | null, threw: boolean): 'up' | 'down' | null {
  if (threw) return 'down';                 // network reject: DNS/refused/aborted — the server is unreachable
  if (status == null) return null;
  if (status >= 502 && status <= 504) return 'down';   // 502/503/504 — gateway/unavailable/timeout = server down
  return 'up';                              // any other answer means the server is reachable
}

export interface ConnectionMonitorOptions {
  /** Ping the server; resolves true when it answers. Default: a HEAD to the client bundle (always served, no auth). */
  ping?: () => Promise<boolean>;
  /** Render the surface for a state. Default: a plain built-in overlay. An app supplies its own here. `retry`/`reload`
   *  are the recovery actions; `attempts` is the reconnect count. Called on every state change (incl. → 'ok', to clear). */
  render?: (state: ConnState, ctx: { attempts: number; retry: () => void; reload: () => void }) => void;
  /** setTimeout, injectable for tests. Returns a canceller. */
  schedule?: (fn: () => void, ms: number) => () => void;
  reload?: () => void;
  /** Backoff schedule (ms) for auto-pings while down; escalates to `lost` once we've exhausted the early tries. */
  backoffMs?: number[];
}

/** How many failed pings before we call it `lost` (vs the softer `reconnecting`). */
const LOST_AFTER = 2;
const DEFAULT_BACKOFF = [1000, 2000, 4000, 8000, 15000];

export class ConnectionMonitor {
  private state: ConnState = 'ok';
  private attempts = 0;
  private cancelTimer: (() => void) | null = null;
  private pinging = false;

  constructor(private readonly o: ConnectionMonitorOptions & { ping: () => Promise<boolean> }) {}

  get current(): ConnState { return this.state; }

  /** The transport calls this after every request. */
  report(outcome: 'up' | 'down' | null): void {
    if (outcome === 'up') this.recover();
    else if (outcome === 'down') this.goDown();
  }

  private goDown(): void {
    if (this.state !== 'ok') return;         // already handling it — the ping loop owns escalation
    this.state = 'reconnecting';
    this.attempts = 0;
    this.emit();
    this.scheduleNextPing(0);
  }

  private recover(): void {
    if (this.state === 'ok') return;
    this.state = 'ok';
    this.attempts = 0;
    this.cancelTimer?.();
    this.cancelTimer = null;
    this.emit();
  }

  /** Manual retry — ping now. */
  retry(): void { void this.pingOnce(); }

  /** Swap the surface renderer after construction. The monitor is built BEFORE the session opens (it wraps the fetch
   *  that opens it), but an app-authored surface (app.Ui.ConnectionSurface) can only be assembled once the session and
   *  the surface's component tree are in hand. Boot builds that renderer then and installs it here, replacing the
   *  built-in default; the next `emit()` (and every state change after) uses it. */
  setRender(render: (state: ConnState, ctx: { attempts: number; retry: () => void; reload: () => void }) => void): void {
    this.o.render = render;
  }

  private scheduleNextPing(delay: number): void {
    this.cancelTimer?.();
    const sched = this.o.schedule ?? ((fn, ms) => { const id = setTimeout(fn, ms); return () => clearTimeout(id); });
    this.cancelTimer = sched(() => { void this.pingOnce(); }, delay);
  }

  private async pingOnce(): Promise<void> {
    if (this.pinging || this.state === 'ok') return;
    this.pinging = true;
    let ok = false;
    try { ok = await this.o.ping(); } catch { ok = false; }
    this.pinging = false;
    // A real request may have recovered us while the ping was in flight (concurrent `report('up')`). Re-read through a
    // local so TS doesn't keep the pre-await narrowing — the field genuinely can be 'ok' again here.
    if ((this.state as ConnState) === 'ok') return;
    if (ok) { this.recover(); return; }
    this.attempts++;
    if (this.state === 'reconnecting' && this.attempts >= LOST_AFTER) { this.state = 'lost'; }
    this.emit();
    const backoff = this.o.backoffMs ?? DEFAULT_BACKOFF;
    this.scheduleNextPing(backoff[Math.min(this.attempts, backoff.length - 1)]);
  }

  private emit(): void {
    const render = this.o.render ?? defaultRender;
    render(this.state, {
      attempts: this.attempts,
      retry: () => this.retry(),
      reload: () => (this.o.reload ?? (() => (globalThis as { location?: { reload(): void } }).location?.reload()))(),
    });
  }

  /** Stop timers (dispose). */
  stop(): void { this.cancelTimer?.(); this.cancelTimer = null; }
}

/** The default (platform) surface — a fixed banner at the top. `reconnecting` is a quiet strip; `lost` is a louder
 *  card with Retry + Reload. Replaced wholesale when an app supplies `app.Ui.ConnectionSurface`. */
export function defaultRender(state: ConnState, ctx: { attempts: number; retry: () => void; reload: () => void }): void {
  const doc = (globalThis as { document?: Document }).document;
  if (!doc?.body) return;
  const ID = 'osy-connection-surface';
  const existing = doc.getElementById(ID);
  if (state === 'ok') { existing?.remove(); return; }

  const box = existing ?? doc.createElement('div');
  box.id = ID;
  box.setAttribute('data-osy-connection', state);
  box.setAttribute('role', 'status');
  const lost = state === 'lost';
  box.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:2147483647;display:flex;gap:.75rem;align-items:center;'
    + 'justify-content:center;padding:.6rem 1rem;font:500 14px/1.4 system-ui,sans-serif;'
    + (lost ? 'background:#7f1d1d;color:#fff;' : 'background:#78350f;color:#fff;');
  const msg = lost ? "Can't reach the server." : 'Reconnecting…';
  box.replaceChildren();
  const label = doc.createElement('span'); label.textContent = msg; box.append(label);
  if (lost) {
    const retry = doc.createElement('button'); retry.textContent = 'Retry';
    retry.style.cssText = 'padding:.3rem .8rem;border-radius:.375rem;border:1px solid #fff6;background:#fff2;color:#fff;cursor:pointer;font:inherit;';
    retry.onclick = () => ctx.retry();
    const reload = doc.createElement('button'); reload.textContent = 'Reload';
    reload.style.cssText = retry.style.cssText;
    reload.onclick = () => ctx.reload();
    box.append(retry, reload);
  }
  if (!existing) doc.body.appendChild(box);
}
