// U5 slice 4d follow-up — the browser WebSocket adapter for the live-data channel. RealtimeClient (src/data/
// realtime.ts) owns the /api/ws subscription PROTOCOL (subscribe/change/unsubscribe + re-subscribe-on-reconnect)
// over an injected WsTransport; this is the one concrete transport that drives a real browser WebSocket. Kept
// thin and injectable (WebSocket factory + schedule) so the buffering/reconnect logic is unit-testable with a
// fake socket and no real network.
//
// AUTH: the server validates a JWT from the `?token=` query param (browsers can't set Authorization on a WS
// upgrade) and REQUIRES application scope — an anonymous token 403s. So boot() only builds this transport for an
// app-scoped session (see boot.ts); an anonymous login page has no `live query` and needs no channel.

import type { WsTransport, WsServerEvent } from '../data/realtime.js';

/** The subset of the DOM `WebSocket` this adapter uses — the browser global satisfies it, and a test supplies a
 *  fake. Handlers are assigned (not addEventListener) to keep the surface minimal. */
export interface WebSocketLike {
  send(data: string): void;
  close(): void;
  onopen: (() => void) | null;
  onclose: (() => void) | null;
  onmessage: ((ev: { data: unknown }) => void) | null;
  onerror: (() => void) | null;
}

export type WebSocketFactory = (url: string) => WebSocketLike;

export interface BrowserWsOptions {
  /** Construct the socket; default `(url) => new WebSocket(url)`. */
  createWebSocket?: WebSocketFactory;
  /** Schedule a reconnect attempt; default `setTimeout`. Injected so tests drive reconnection deterministically. */
  schedule?: (fn: () => void, ms: number) => void;
  /** Initial reconnect delay; doubles up to `maxReconnectDelayMs`. */
  reconnectDelayMs?: number;
  maxReconnectDelayMs?: number;
  /** Stop reconnecting after this many consecutive closes that never produced an open (default 6). A transient drop
   *  resets the count on its next open; a handshake the server keeps refusing — an expired token — never does. */
  maxConsecutiveFailures?: number;
  /** Called ONCE when reconnection is abandoned (see `maxConsecutiveFailures`). The socket stays closed; the app should
   *  treat this as "this session can no longer receive live data" and route to re-auth. */
  onGiveUp?: () => void;
}

/** A WsTransport backed by a real (or injected) browser WebSocket: sends buffer until the socket opens, incoming
 *  text frames parse to WsServerEvents, and a dropped socket auto-reconnects with capped backoff (firing the
 *  reconnect handlers so RealtimeClient re-subscribes its active set). */
export function browserWsTransport(url: string, opts: BrowserWsOptions = {}): WsTransport {
  const createWebSocket = opts.createWebSocket ?? ((u) => new WebSocket(u) as unknown as WebSocketLike);
  const schedule = opts.schedule ?? ((fn, ms) => { setTimeout(fn, ms); });
  const baseDelay = opts.reconnectDelayMs ?? 1000;
  const maxDelay = opts.maxReconnectDelayMs ?? 15000;

  const maxFailures = opts.maxConsecutiveFailures ?? 6;

  const messageHandlers = new Set<(m: WsServerEvent) => void>();
  const reconnectHandlers = new Set<() => void>();
  let socket: WebSocketLike | null = null;
  let open = false;
  let everOpened = false;
  let outbox: string[] = [];
  let delay = baseDelay;
  // Consecutive closes with NO successful open in between. A transient drop resets this on the next open; a handshake
  // the server keeps REFUSING never does — which is the expired-session case (see giveUp below).
  let failuresSinceOpen = 0;
  let abandoned = false;

  function connect(): void {
    const ws = createWebSocket(url);
    socket = ws;
    ws.onopen = () => {
      open = true;
      delay = baseDelay; // reset backoff on a good connect
      failuresSinceOpen = 0;
      const pending = outbox;
      outbox = [];
      for (const msg of pending) ws.send(msg);
      // onReconnect is a RE-establish signal (RealtimeClient re-subscribes its active set). The first open has no
      // active subs, so fire only on subsequent opens.
      if (everOpened) for (const h of reconnectHandlers) h();
      everOpened = true;
    };
    ws.onmessage = (ev) => {
      const parsed = parseEvent(ev.data);
      if (parsed) for (const h of messageHandlers) h(parsed);
    };
    ws.onclose = () => {
      open = false;
      socket = null;
      // GIVE UP after `maxFailures` closes that never produced an open. A browser deliberately hides the handshake's
      // HTTP status from script, so a 401 (expired/invalid token) is indistinguishable from a transient drop by status
      // alone — but not by SHAPE: a real drop reconnects and resets this counter, while a refused handshake never
      // does. Retrying it forever is what put 2000+ `/api/ws → 401` lines in one dev log, one every 15s per stale tab,
      // for a session that could never come back. Stopping is also the only way the app can TELL the user: `onGiveUp`
      // routes to the same re-auth path a 401 on any other request takes, instead of a page that quietly never updates.
      failuresSinceOpen++;
      if (failuresSinceOpen >= maxFailures) {
        abandoned = true;
        opts.onGiveUp?.();
        return;
      }
      schedule(connect, delay);
      delay = Math.min(delay * 2, maxDelay);
    };
    ws.onerror = () => { /* onclose follows and drives the reconnect; nothing to do here */ };
  }

  connect();

  return {
    send(message: unknown): void {
      // Once abandoned there is no next open to flush into, so buffering would grow a queue that is never drained
      // (every later subscribe would pile on). Drop instead — the caller's data path is the refetch, not this.
      if (abandoned) return;
      const data = JSON.stringify(message);
      if (open && socket) socket.send(data);
      else outbox.push(data); // buffered; flushed on the next open
    },
    onMessage(handler: (message: WsServerEvent) => void): () => void {
      messageHandlers.add(handler);
      return () => messageHandlers.delete(handler);
    },
    onReconnect(handler: () => void): () => void {
      reconnectHandlers.add(handler);
      return () => reconnectHandlers.delete(handler);
    },
    /** [[M174]] — stop for good. Reuses `abandoned`, which already means exactly this to the rest of this factory:
     *  no reconnect on close, no buffering in `send`. Setting it BEFORE closing the socket is what makes it a stop
     *  rather than a drop — `onclose` reads the flag and returns instead of scheduling the backoff, so the abandoned
     *  page does not come straight back with a fresh socket.
     *
     *  <p>Handlers are dropped too: a closing socket can still deliver a queued frame, and a disposed page's handlers
     *  are exactly the ones that must not run.</p> */
    close(): void {
      abandoned = true;
      messageHandlers.clear();
      reconnectHandlers.clear();
      outbox = [];
      const ws = socket;
      socket = null;
      open = false;
      if (ws) { try { ws.close(); } catch { /* already closing/closed — nothing to stop */ } }
    },
  };
}

/** Parse a server frame (text JSON) into a WsServerEvent; non-JSON / non-object frames are dropped (never trust
 *  the wire to be well-formed). */
function parseEvent(data: unknown): WsServerEvent | null {
  if (typeof data !== 'string') return null;
  try {
    const obj = JSON.parse(data) as unknown;
    if (obj && typeof obj === 'object' && typeof (obj as { event?: unknown }).event === 'string') {
      return obj as WsServerEvent;
    }
  } catch {
    // ignore malformed frames
  }
  return null;
}
