// D-3D1 — THE 3D LAYER of the `Canvas` atom: `Mesh.*` builds geometry, `Draw.Camera/Light/Fog` set a frame's state,
// `Draw.Mesh` places a mesh, and `flushInto` renders the lot through WebGL and composites it onto the component's 2D
// context, so a `Draw.Text` after it is a HUD and a `Draw.Clear` before it is the sky.
//
// ⚑ WHY THE 2D SURFACE COULD NOT DO THIS. Every 2D verb is a filled shape; the only route to a SHADED scene was
// `Draw.Pixels` fed by a software rasteriser in Osy#, and that path is bounded at ~10,000 px/frame however well the
// loop is lowered (D233) — a lit 1280x720 frame is 92 times that. Lighting, shadows, fog and tone mapping are
// per-pixel work and belong on the GPU. What an `on frame` body should do is say WHAT is where: ~50 host calls a
// frame for a whole low-poly world, and a kernel makes each of those a direct call (D255).
//
// THE PICTURE it makes is the low-poly look: flat shading from per-face normals (every vertex is UNSHARED, which is
// what makes a sphere read as facets rather than a smooth ball), ONE directional sun with a shadow map and 3x3
// percentage-closer filtering, a hemisphere ambient (the sky colour from above, a darker version of it from below),
// linear distance fog, and ACES tone mapping. Colour is per draw; there are no materials or textures — that is the
// closed set a game of this kind needs, and it grows by adding a case.
//
// ⚠ TWO HALVES, AND ONLY ONE NEEDS A BROWSER. Geometry and matrices are pure arithmetic and are unit-tested in
// happy-dom, which has no WebGL. `Scene3d` is the GL half; the visual harness (real Chromium) is the only thing that
// can see what it paints, and `tests/e2e/visual/suites/demo-arcade-birds.mjs` is what does.

/** The value a `Mesh.*` builder answers and `Draw.Mesh` takes. A PLAIN object on purpose: a lowered kernel's value
 *  guard admits an object literal without asking the host, so a mesh held in a field flows through an `on frame`
 *  kernel untouched. The triangles are unshared (three vertices per face) with the face normal on each, and the
 *  bounding sphere is what fits the shadow frustum to what is actually drawn. */
export interface MeshHandle {
  readonly osyMesh: true;
  /** x, y, z per vertex, three vertices per triangle. */
  readonly positions: Float32Array;
  /** The face normal, repeated on each of the face's three vertices. */
  readonly normals: Float32Array;
  readonly vertexCount: number;
  readonly center: readonly [number, number, number];
  readonly radius: number;
}

export function isMesh(v: unknown): v is MeshHandle {
  return typeof v === 'object' && v !== null && (v as { osyMesh?: unknown }).osyMesh === true;
}

// ── GEOMETRY ──────────────────────────────────────────────────────────────────────────────────────────────────────

/** Build a handle from a flat list of triangles (nine numbers each). Normals are computed from the winding, so a
 *  triangle wound counter-clockwise seen from outside faces outward — the convention `Mesh.From` documents. */
function fromTriangles(tri: number[]): MeshHandle {
  const positions = new Float32Array(tri);
  const normals = new Float32Array(tri.length);
  let minX = Infinity, minY = Infinity, minZ = Infinity, maxX = -Infinity, maxY = -Infinity, maxZ = -Infinity;
  for (let i = 0; i < tri.length; i += 9) {
    const ax = tri[i], ay = tri[i + 1], az = tri[i + 2];
    const bx = tri[i + 3], by = tri[i + 4], bz = tri[i + 5];
    const cx = tri[i + 6], cy = tri[i + 7], cz = tri[i + 8];
    const ux = bx - ax, uy = by - ay, uz = bz - az, vx = cx - ax, vy = cy - ay, vz = cz - az;
    let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
    const len = Math.hypot(nx, ny, nz) || 1;
    nx /= len; ny /= len; nz /= len;
    for (let k = 0; k < 9; k += 3) { normals[i + k] = nx; normals[i + k + 1] = ny; normals[i + k + 2] = nz; }
    for (let k = 0; k < 9; k += 3) {
      const x = tri[i + k], y = tri[i + k + 1], z = tri[i + k + 2];
      if (x < minX) minX = x; if (x > maxX) maxX = x;
      if (y < minY) minY = y; if (y > maxY) maxY = y;
      if (z < minZ) minZ = z; if (z > maxZ) maxZ = z;
    }
  }
  if (tri.length === 0) { minX = minY = minZ = maxX = maxY = maxZ = 0; }
  const center: [number, number, number] = [(minX + maxX) / 2, (minY + maxY) / 2, (minZ + maxZ) / 2];
  const radius = Math.hypot(maxX - minX, maxY - minY, maxZ - minZ) / 2;
  return { osyMesh: true, positions, normals, vertexCount: tri.length / 3, center, radius };
}

type V3 = [number, number, number];
const push = (out: number[], a: V3, b: V3, c: V3): void => { out.push(a[0], a[1], a[2], b[0], b[1], b[2], c[0], c[1], c[2]); };
const quad = (out: number[], a: V3, b: V3, c: V3, d: V3): void => { push(out, a, b, c); push(out, a, c, d); };

/** `Mesh.Box(w, h, d)` — an axis-aligned box centred on the origin, faces wound outward. */
export function box(w: number, h: number, d: number): MeshHandle {
  const x = w / 2, y = h / 2, z = d / 2;
  const out: number[] = [];
  quad(out, [-x, -y, z], [x, -y, z], [x, y, z], [-x, y, z]);        // +z
  quad(out, [x, -y, -z], [-x, -y, -z], [-x, y, -z], [x, y, -z]);    // -z
  quad(out, [x, -y, z], [x, -y, -z], [x, y, -z], [x, y, z]);        // +x
  quad(out, [-x, -y, -z], [-x, -y, z], [-x, y, z], [-x, y, -z]);    // -x
  quad(out, [-x, y, z], [x, y, z], [x, y, -z], [-x, y, -z]);        // +y
  quad(out, [-x, -y, -z], [x, -y, -z], [x, -y, z], [-x, -y, z]);    // -y
  return fromTriangles(out);
}

/** `Mesh.Plane(w, d)` — a flat sheet in the xz plane at y = 0, facing up. */
export function plane(w: number, d: number): MeshHandle {
  const x = w / 2, z = d / 2;
  const out: number[] = [];
  quad(out, [-x, 0, z], [x, 0, z], [x, 0, -z], [-x, 0, -z]);
  return fromTriangles(out);
}

/** `Mesh.Cylinder(radiusTop, radiusBottom, height, segments)` — along y, centred on the origin. A zero radius at
 *  either end makes a cone, and either cap is omitted when its radius is zero. */
export function cylinder(rTop: number, rBottom: number, height: number, segments: number): MeshHandle {
  const n = Math.max(3, Math.trunc(segments));
  const y0 = -height / 2, y1 = height / 2;
  const out: number[] = [];
  const ring = (r: number, y: number, i: number): V3 => {
    const a = (i / n) * Math.PI * 2;
    return [Math.cos(a) * r, y, Math.sin(a) * r];
  };
  for (let i = 0; i < n; i++) {
    const b0 = ring(rBottom, y0, i), b1 = ring(rBottom, y0, i + 1);
    const t0 = ring(rTop, y1, i), t1 = ring(rTop, y1, i + 1);
    // The side, wound so the outward face is counter-clockwise from outside: bottom i → bottom i+1 runs clockwise
    // seen from above (the ring goes +x → +z), so the outward triangle is b1, b0, t0.
    if (rTop > 0 && rBottom > 0) { push(out, b1, b0, t0); push(out, b1, t0, t1); }
    else if (rBottom > 0) push(out, b1, b0, [0, y1, 0]);
    else if (rTop > 0) push(out, t0, t1, [0, y0, 0]);
    // The caps run the ring the OTHER way from the side: seen from +y the ring is clockwise, so the top cap wants
    // centre, i+1, i to face up, and the bottom cap centre, i, i+1 to face down. (Both were wound the other way
    // once — with back-face culling that is not a dark cap, it is NO cap. `scene3d.test.ts` holds every face.)
    if (rTop > 0) push(out, [0, y1, 0], t1, t0);        // top cap, facing +y
    if (rBottom > 0) push(out, [0, y0, 0], b0, b1);     // bottom cap, facing -y
  }
  return fromTriangles(out);
}

/** `Mesh.Cone(radius, height, segments)` — a cylinder with a point on top. */
export function cone(radius: number, height: number, segments: number): MeshHandle {
  return cylinder(0, radius, height, segments);
}

/** `Mesh.Sphere(radius, detail)` — an icosphere: 20 faces at detail 0, times four per level. Flat-shaded like
 *  everything else, which at detail 1 or 2 is the faceted ball the low-poly look wants. Detail is capped at 4
 *  (5,120 faces): beyond that a sphere is smooth anyway and the buffer is only cost. */
export function sphere(radius: number, detail: number): MeshHandle {
  const t = (1 + Math.sqrt(5)) / 2;
  const base: V3[] = [
    [-1, t, 0], [1, t, 0], [-1, -t, 0], [1, -t, 0],
    [0, -1, t], [0, 1, t], [0, -1, -t], [0, 1, -t],
    [t, 0, -1], [t, 0, 1], [-t, 0, -1], [-t, 0, 1],
  ].map(v => norm(v as V3));
  let faces: [V3, V3, V3][] = [
    [0, 11, 5], [0, 5, 1], [0, 1, 7], [0, 7, 10], [0, 10, 11],
    [1, 5, 9], [5, 11, 4], [11, 10, 2], [10, 7, 6], [7, 1, 8],
    [3, 9, 4], [3, 4, 2], [3, 2, 6], [3, 6, 8], [3, 8, 9],
    [4, 9, 5], [2, 4, 11], [6, 2, 10], [8, 6, 7], [9, 8, 1],
  ].map(([a, b, c]) => [base[a], base[b], base[c]]);
  const levels = Math.min(4, Math.max(0, Math.trunc(detail)));
  for (let l = 0; l < levels; l++) {
    const next: [V3, V3, V3][] = [];
    for (const [a, b, c] of faces) {
      const ab = norm(mid(a, b)), bc = norm(mid(b, c)), ca = norm(mid(c, a));
      next.push([a, ab, ca], [b, bc, ab], [c, ca, bc], [ab, bc, ca]);
    }
    faces = next;
  }
  const out: number[] = [];
  for (const [a, b, c] of faces) push(out, scale(a, radius), scale(b, radius), scale(c, radius));
  return fromTriangles(out);
}

/** `Mesh.From(vertices, indices)` — x, y, z per vertex and three vertex numbers per triangle, counter-clockwise seen
 *  from outside. A bad index is an ERROR naming it, not a silently skipped face: this is the one builder fed by app
 *  data, and a heightfield with an off-by-one would otherwise render with a hole nobody could locate. */
export function from(vertices: ArrayLike<number>, indices: ArrayLike<number>): MeshHandle {
  if (vertices.length % 3 !== 0)
    throw new Error(`Mesh.From: \`vertices\` has ${vertices.length} numbers, which is not a whole number of x, y, z triples`);
  if (indices.length % 3 !== 0)
    throw new Error(`Mesh.From: \`indices\` has ${indices.length} entries, which is not a whole number of triangles (three per face)`);
  const count = vertices.length / 3;
  const out: number[] = new Array(indices.length * 3);
  for (let i = 0; i < indices.length; i++) {
    const ix = Number(indices[i]);
    if (!Number.isInteger(ix) || ix < 0 || ix >= count)
      throw new Error(`Mesh.From: index ${indices[i]} at position ${i} is outside the ${count} vertices given`);
    out[i * 3] = Number(vertices[ix * 3]); out[i * 3 + 1] = Number(vertices[ix * 3 + 1]); out[i * 3 + 2] = Number(vertices[ix * 3 + 2]);
  }
  return fromTriangles(out);
}

const norm = (v: V3): V3 => { const l = Math.hypot(v[0], v[1], v[2]) || 1; return [v[0] / l, v[1] / l, v[2] / l]; };
const mid = (a: V3, b: V3): V3 => [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2];
const scale = (v: V3, s: number): V3 => [v[0] * s, v[1] * s, v[2] * s];

// ── MATRICES — column-major 4x4, the layout WebGL uploads ─────────────────────────────────────────────────────

export type Mat4 = Float32Array;

export function perspective(fovyDeg: number, aspect: number, near: number, far: number): Mat4 {
  const f = 1 / Math.tan((fovyDeg * Math.PI) / 360);
  const m = new Float32Array(16);
  m[0] = f / aspect; m[5] = f;
  m[10] = (far + near) / (near - far); m[11] = -1;
  m[14] = (2 * far * near) / (near - far);
  return m;
}

export function ortho(l: number, r: number, b: number, t: number, n: number, f: number): Mat4 {
  const m = new Float32Array(16);
  m[0] = 2 / (r - l); m[5] = 2 / (t - b); m[10] = -2 / (f - n);
  m[12] = -(r + l) / (r - l); m[13] = -(t + b) / (t - b); m[14] = -(f + n) / (f - n); m[15] = 1;
  return m;
}

export function lookAt(eye: V3, target: V3, up: V3 = [0, 1, 0]): Mat4 {
  let zx = eye[0] - target[0], zy = eye[1] - target[1], zz = eye[2] - target[2];
  let l = Math.hypot(zx, zy, zz) || 1; zx /= l; zy /= l; zz /= l;
  // An eye looking straight along `up` has no sideways: pick another up rather than a NaN matrix.
  if (Math.abs(zx * up[0] + zy * up[1] + zz * up[2]) > 0.999) up = [0, 0, 1];
  let xx = up[1] * zz - up[2] * zy, xy = up[2] * zx - up[0] * zz, xz = up[0] * zy - up[1] * zx;
  l = Math.hypot(xx, xy, xz) || 1; xx /= l; xy /= l; xz /= l;
  const yx = zy * xz - zz * xy, yy = zz * xx - zx * xz, yz = zx * xy - zy * xx;
  const m = new Float32Array(16);
  m[0] = xx; m[1] = yx; m[2] = zx;
  m[4] = xy; m[5] = yy; m[6] = zy;
  m[8] = xz; m[9] = yz; m[10] = zz;
  m[12] = -(xx * eye[0] + xy * eye[1] + xz * eye[2]);
  m[13] = -(yx * eye[0] + yy * eye[1] + yz * eye[2]);
  m[14] = -(zx * eye[0] + zy * eye[1] + zz * eye[2]);
  m[15] = 1;
  return m;
}

export function multiply(a: Mat4, b: Mat4, out: Mat4 = new Float32Array(16)): Mat4 {
  for (let c = 0; c < 4; c++) {
    const b0 = b[c * 4], b1 = b[c * 4 + 1], b2 = b[c * 4 + 2], b3 = b[c * 4 + 3];
    out[c * 4] = a[0] * b0 + a[4] * b1 + a[8] * b2 + a[12] * b3;
    out[c * 4 + 1] = a[1] * b0 + a[5] * b1 + a[9] * b2 + a[13] * b3;
    out[c * 4 + 2] = a[2] * b0 + a[6] * b1 + a[10] * b2 + a[14] * b3;
    out[c * 4 + 3] = a[3] * b0 + a[7] * b1 + a[11] * b2 + a[15] * b3;
  }
  return out;
}

/** Transform a point (w = 1) and return x, y, z, w. */
export function transformPoint(m: Mat4, p: V3): [number, number, number, number] {
  return [
    m[0] * p[0] + m[4] * p[1] + m[8] * p[2] + m[12],
    m[1] * p[0] + m[5] * p[1] + m[9] * p[2] + m[13],
    m[2] * p[0] + m[6] * p[1] + m[10] * p[2] + m[14],
    m[3] * p[0] + m[7] * p[1] + m[11] * p[2] + m[15],
  ];
}

/** The model matrix of a `Draw.Mesh` — translate · rotate Z · rotate Y · rotate X · scale, so `rx` is applied first:
 *  pitch the bird, then yaw it to its heading, then place it. Radians, like `Math.Sin`. */
export function modelMatrix(x: number, y: number, z: number, rx: number, ry: number, rz: number,
  sx: number, sy: number, sz: number, out: Mat4 = new Float32Array(16)): Mat4 {
  const cx = Math.cos(rx), sxn = Math.sin(rx), cy = Math.cos(ry), syn = Math.sin(ry), cz = Math.cos(rz), szn = Math.sin(rz);
  // R = Rz * Ry * Rx
  const r00 = cz * cy, r01 = cz * syn * sxn - szn * cx, r02 = cz * syn * cx + szn * sxn;
  const r10 = szn * cy, r11 = szn * syn * sxn + cz * cx, r12 = szn * syn * cx - cz * sxn;
  const r20 = -syn, r21 = cy * sxn, r22 = cy * cx;
  out[0] = r00 * sx; out[1] = r10 * sx; out[2] = r20 * sx; out[3] = 0;
  out[4] = r01 * sy; out[5] = r11 * sy; out[6] = r21 * sy; out[7] = 0;
  out[8] = r02 * sz; out[9] = r12 * sz; out[10] = r22 * sz; out[11] = 0;
  out[12] = x; out[13] = y; out[14] = z; out[15] = 1;
  return out;
}

/** The inverse-transpose of a model matrix's 3x3, which is what carries a normal correctly under a NON-uniform
 *  scale (a stretched sphere's normals lean the wrong way under the plain matrix). Column-major 3x3. */
export function normalMatrix(m: Mat4, out: Float32Array = new Float32Array(9)): Float32Array {
  const a00 = m[0], a01 = m[1], a02 = m[2], a10 = m[4], a11 = m[5], a12 = m[6], a20 = m[8], a21 = m[9], a22 = m[10];
  const b01 = a22 * a11 - a12 * a21, b11 = -a22 * a10 + a12 * a20, b21 = a21 * a10 - a11 * a20;
  let det = a00 * b01 + a01 * b11 + a02 * b21;
  if (!det) det = 1;
  det = 1 / det;
  out[0] = b01 * det; out[1] = (-a22 * a01 + a02 * a21) * det; out[2] = (a12 * a01 - a02 * a11) * det;
  out[3] = b11 * det; out[4] = (a22 * a00 - a02 * a20) * det; out[5] = (-a12 * a00 + a02 * a10) * det;
  out[6] = b21 * det; out[7] = (-a21 * a00 + a01 * a20) * det; out[8] = (a11 * a00 - a01 * a10) * det;
  // The inverse above is in the same layout as the input; the TRANSPOSE is what a normal wants.
  const t1 = out[1], t2 = out[2], t5 = out[5];
  out[1] = out[3]; out[3] = t1; out[2] = out[6]; out[6] = t2; out[5] = out[7]; out[7] = t5;
  return out;
}

// ── COLOUR — the same strings the 2D verbs take, as linear RGB for the shader ─────────────────────────────────

const colourCache = new Map<string, V3>();

/** `#rgb`, `#rrggbb`, `rgb(r, g, b)` or `rgba(…)` (alpha ignored — a mesh is opaque) → sRGB 0..1. Anything else
 *  is magenta, which is the colour every renderer uses to mean "you typed this wrong", and it is loud on purpose. */
export function parseColour(s: string): V3 {
  const hit = colourCache.get(s);
  if (hit) return hit;
  let v: V3 = [1, 0, 1];
  const t = s.trim();
  if (t.startsWith('#')) {
    const h = t.slice(1);
    if (h.length === 3 || h.length === 4) v = [parseInt(h[0] + h[0], 16) / 255, parseInt(h[1] + h[1], 16) / 255, parseInt(h[2] + h[2], 16) / 255];
    else if (h.length === 6 || h.length === 8) v = [parseInt(h.slice(0, 2), 16) / 255, parseInt(h.slice(2, 4), 16) / 255, parseInt(h.slice(4, 6), 16) / 255];
  } else {
    const m = /^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/i.exec(t);
    if (m) v = [Number(m[1]) / 255, Number(m[2]) / 255, Number(m[3]) / 255];
  }
  if (v.some(c => Number.isNaN(c))) v = [1, 0, 1];
  colourCache.set(s, v);
  return v;
}

const toLinear = (c: number): number => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));
export function linearColour(s: string): V3 { const c = parseColour(s); return [toLinear(c[0]), toLinear(c[1]), toLinear(c[2])]; }

// ── THE GL HALF ───────────────────────────────────────────────────────────────────────────────────────────────

interface Draw { mesh: MeshHandle; model: Mat4; colour: V3; worldCenter: V3; worldRadius: number; }
interface GpuMesh { pos: WebGLBuffer; nrm: WebGLBuffer; count: number; }

const SHADOW_SIZE = 2048;

const MAIN_VS = `
attribute vec3 aPos; attribute vec3 aNrm;
uniform mat4 uModel; uniform mat4 uViewProj; uniform mat4 uLightVP; uniform mat3 uNormal;
varying vec3 vNrm; varying vec4 vShadow; varying vec3 vWorld;
void main() {
  vec4 w = uModel * vec4(aPos, 1.0);
  vNrm = normalize(uNormal * aNrm);
  vShadow = uLightVP * w;
  vWorld = w.xyz;
  gl_Position = uViewProj * w;
}`;

const MAIN_FS = `
precision highp float;
uniform vec3 uColor; uniform vec3 uSunDir; uniform vec3 uSunColor; uniform vec3 uAmbient;
uniform vec3 uFogColor; uniform vec2 uFog; uniform sampler2D uShadow; uniform float uShadowOn; uniform float uTexel;
uniform vec3 uEye;
varying vec3 vNrm; varying vec4 vShadow; varying vec3 vWorld;
float unpack(vec4 c) { return dot(c, vec4(1.0, 1.0 / 255.0, 1.0 / 65025.0, 1.0 / 16581375.0)); }
vec3 aces(vec3 x) { return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0); }
void main() {
  vec3 n = normalize(vNrm);
  float ndl = max(dot(n, uSunDir), 0.0);
  float lit = 1.0;
  if (uShadowOn > 0.5) {
    vec3 p = vShadow.xyz / vShadow.w * 0.5 + 0.5;
    if (p.x > 0.0 && p.x < 1.0 && p.y > 0.0 && p.y < 1.0 && p.z < 1.0) {
      float bias = max(0.003 * (1.0 - ndl), 0.0008);
      float s = 0.0;
      for (int dx = -1; dx <= 1; dx++) for (int dy = -1; dy <= 1; dy++) {
        float d = unpack(texture2D(uShadow, p.xy + vec2(float(dx), float(dy)) * uTexel));
        s += (p.z - bias > d) ? 0.0 : 1.0;
      }
      lit = s / 9.0;
    }
  }
  // Hemisphere ambient: the sky colour lights a face pointing up, a darker version lights one pointing down.
  float hemi = n.y * 0.5 + 0.5;
  vec3 ambient = mix(uAmbient * 0.3, uAmbient, hemi);
  vec3 col = uColor * (ambient + uSunColor * ndl * lit);
  col = pow(aces(col), vec3(1.0 / 2.2));
  // Fog AFTER tone mapping, in display space — so a far object is exactly the sky the 2D layer painted, and the
  // horizon has no seam. The distance is taken PER FRAGMENT from the interpolated world position, never per vertex:
  // a ground plane is one big quad whose corners are all beyond the fog, and a per-vertex distance interpolated
  // across it fogs the whole plane out — including the part eight units from the eye. That is how an entire
  // valley floor rendered as flat sky-colour and read as "the plane did not draw".
  float f = clamp((length(vWorld - uEye) - uFog.x) / max(uFog.y - uFog.x, 0.001), 0.0, 1.0);
  gl_FragColor = vec4(mix(col, uFogColor, f), 1.0);
}`;

const SHADOW_VS = `
attribute vec3 aPos; uniform mat4 uModel; uniform mat4 uLightVP;
void main() { gl_Position = uLightVP * uModel * vec4(aPos, 1.0); }`;

// Depth packed into RGBA8, so the shadow map needs no depth-texture extension on WebGL1 and no float target
// anywhere: four bytes of an ordinary colour attachment carry 32 bits of depth.
const SHADOW_FS = `
precision highp float;
void main() {
  vec4 e = fract(gl_FragCoord.z * vec4(1.0, 255.0, 65025.0, 16581375.0));
  gl_FragColor = e - e.yzww * vec4(1.0 / 255.0, 1.0 / 255.0, 1.0 / 255.0, 0.0);
}`;

/** One per drawing component: the offscreen GL canvas, its programs, the uploaded meshes, and the frame state the
 *  `Draw.Camera/Light/Fog` verbs set. Frame state PERSISTS across frames — a camera set once in `on mount` stays —
 *  while the draw list is cleared by every flush. */
export class Scene3d {
  private readonly canvas: HTMLCanvasElement;
  private gl: WebGLRenderingContext | null = null;
  private failed = false;
  private main: WebGLProgram | null = null;
  private shadow: WebGLProgram | null = null;
  private shadowFbo: WebGLFramebuffer | null = null;
  private shadowTex: WebGLTexture | null = null;
  private readonly uploaded = new WeakMap<MeshHandle, GpuMesh>();
  private readonly draws: Draw[] = [];
  private readonly loc = new Map<string, WebGLUniformLocation | null>();

  // Frame state, with the defaults a first frame with no `Draw.Camera` gets: eye slightly above and behind the
  // origin looking at it, a warm sun from the upper left, no fog (far beyond anything).
  private eye: V3 = [0, 3, 10];
  private target: V3 = [0, 0, 0];
  private fov = 50;
  private sunDir: V3 = norm([0.4, 1, 0.6]);      // TOWARDS the light (negated from the "shines along" the verb takes)
  private sunColour: V3 = linearColour('#fff4e0');
  private ambient: V3 = linearColour('#7f9fbf');
  private fogColour: V3 = parseColour('#000000');
  private fogNear = 1e9;
  private fogFar = 2e9;

  /** True while `Draw.Mesh` calls are waiting to be rendered — what tells the walker a 2D verb must flush first. */
  get pending(): boolean { return this.draws.length > 0; }

  constructor() {
    this.canvas = document.createElement('canvas');
  }

  camera(ex: number, ey: number, ez: number, tx: number, ty: number, tz: number, fovDeg: number): void {
    this.eye = [ex, ey, ez]; this.target = [tx, ty, tz];
    this.fov = Math.min(170, Math.max(1, fovDeg || 50));
  }

  light(dx: number, dy: number, dz: number, colour: string, ambient: string): void {
    // The verb takes the direction the sun SHINES ALONG (down is (0, -1, 0)); the shader wants the direction TO it.
    this.sunDir = norm([-dx, -dy, -dz]);
    this.sunColour = linearColour(colour);
    this.ambient = linearColour(ambient);
  }

  fog(colour: string, near: number, far: number): void {
    this.fogColour = parseColour(colour);
    this.fogNear = near; this.fogFar = Math.max(far, near + 0.001);
  }

  /** `Draw.Mesh` — queue one placement. `xform` is 3 (x y z), 7 (+ rx ry rz scale) or 9 (+ sx sy sz) numbers. */
  draw(mesh: MeshHandle, xform: readonly number[], colour: string): void {
    const [x, y, z] = [xform[0] ?? 0, xform[1] ?? 0, xform[2] ?? 0];
    const rx = xform.length >= 7 ? xform[3] : 0, ry = xform.length >= 7 ? xform[4] : 0, rz = xform.length >= 7 ? xform[5] : 0;
    let sx = 1, sy = 1, sz = 1;
    if (xform.length >= 9) { sx = xform[6]; sy = xform[7]; sz = xform[8]; }
    else if (xform.length >= 7) { sx = sy = sz = xform[6]; }
    const model = modelMatrix(x, y, z, rx, ry, rz, sx, sy, sz);
    const c = transformPoint(model, mesh.center as V3);
    this.draws.push({
      mesh, model, colour: linearColour(colour),
      worldCenter: [c[0], c[1], c[2]],
      worldRadius: mesh.radius * Math.max(Math.abs(sx), Math.abs(sy), Math.abs(sz)),
    });
  }

  /** Render the queued draws and composite them onto `target` at (0, 0). Clears the queue either way. */
  flushInto(target: CanvasRenderingContext2D): void {
    const draws = this.draws.splice(0);
    if (draws.length === 0) return;
    const gl = this.context();
    if (!gl) return;
    const w = target.canvas.width, h = target.canvas.height;
    if (this.canvas.width !== w || this.canvas.height !== h) { this.canvas.width = w; this.canvas.height = h; }

    // ── shadow pass: an orthographic view along the sun, fitted to what is drawn near the camera's target ──
    let minX = Infinity, minY = Infinity, minZ = Infinity, maxX = -Infinity, maxY = -Infinity, maxZ = -Infinity;
    for (const d of draws) {
      const [cx, cy, cz] = d.worldCenter, r = d.worldRadius;
      if (cx - r < minX) minX = cx - r; if (cx + r > maxX) maxX = cx + r;
      if (cy - r < minY) minY = cy - r; if (cy + r > maxY) maxY = cy + r;
      if (cz - r < minZ) minZ = cz - r; if (cz + r > maxZ) maxZ = cz + r;
    }
    const sceneCenter: V3 = [(minX + maxX) / 2, (minY + maxY) / 2, (minZ + maxZ) / 2];
    const sceneRadius = Math.max(1, Math.hypot(maxX - minX, maxY - minY, maxZ - minZ) / 2);
    // A whole world in one 2048² map is a blurry shadow under everything; what the eye is looking at is what
    // deserves the texels. So the map covers at most a region around the camera's target, sized by the fog (what is
    // beyond the fog casts no visible shadow) or a fixed radius when there is none.
    const wanted = this.fogFar < 1e8 ? this.fogFar * 0.6 : 40;
    const shadowRadius = Math.min(sceneRadius, Math.max(8, wanted));
    const shadowCenter = shadowRadius < sceneRadius ? this.target : sceneCenter;
    const lightEye: V3 = [
      shadowCenter[0] + this.sunDir[0] * sceneRadius * 2,
      shadowCenter[1] + this.sunDir[1] * sceneRadius * 2,
      shadowCenter[2] + this.sunDir[2] * sceneRadius * 2,
    ];
    const lightView = lookAt(lightEye, shadowCenter);
    const lightProj = ortho(-shadowRadius, shadowRadius, -shadowRadius, shadowRadius, 0.1, sceneRadius * 4 + 1);
    const lightVP = multiply(lightProj, lightView);

    const shadowsOn = this.shadow !== null && this.shadowFbo !== null;
    if (shadowsOn) {
      gl.bindFramebuffer(gl.FRAMEBUFFER, this.shadowFbo);
      gl.viewport(0, 0, SHADOW_SIZE, SHADOW_SIZE);
      gl.clearColor(1, 1, 1, 1);
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
      gl.useProgram(this.shadow);
      gl.uniformMatrix4fv(this.u('s', 'uLightVP'), false, lightVP);
      // Front faces into the shadow map, so a surface never shadows itself along its lit side. Back-face culling
      // would leave a thin sheet (a Plane) casting nothing, and the ground is a Plane.
      gl.enable(gl.CULL_FACE); gl.cullFace(gl.FRONT);
      const aPos = gl.getAttribLocation(this.shadow!, 'aPos');
      for (const d of draws) {
        const g = this.upload(gl, d.mesh);
        gl.uniformMatrix4fv(this.u('s', 'uModel'), false, d.model);
        gl.bindBuffer(gl.ARRAY_BUFFER, g.pos); gl.enableVertexAttribArray(aPos); gl.vertexAttribPointer(aPos, 3, gl.FLOAT, false, 0, 0);
        gl.drawArrays(gl.TRIANGLES, 0, g.count);
      }
      gl.cullFace(gl.BACK);
    }

    // ── main pass ──
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.viewport(0, 0, w, h);
    gl.clearColor(0, 0, 0, 0);       // transparent: whatever the 2D layer painted before shows through as the sky
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    gl.useProgram(this.main);
    const view = lookAt(this.eye, this.target);
    const far = Math.max(200, this.fogFar < 1e8 ? this.fogFar * 1.5 : 0);
    const proj = perspective(this.fov, w / Math.max(1, h), 0.1, far);
    gl.uniformMatrix4fv(this.u('m', 'uViewProj'), false, multiply(proj, view));
    gl.uniformMatrix4fv(this.u('m', 'uLightVP'), false, lightVP);
    gl.uniform3fv(this.u('m', 'uEye'), this.eye);
    gl.uniform3fv(this.u('m', 'uSunDir'), this.sunDir);
    gl.uniform3fv(this.u('m', 'uSunColor'), this.sunColour);
    gl.uniform3fv(this.u('m', 'uAmbient'), this.ambient);
    gl.uniform3fv(this.u('m', 'uFogColor'), this.fogColour);
    gl.uniform2f(this.u('m', 'uFog'), this.fogNear, this.fogFar);
    gl.uniform1f(this.u('m', 'uShadowOn'), shadowsOn ? 1 : 0);
    gl.uniform1f(this.u('m', 'uTexel'), 1 / SHADOW_SIZE);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.shadowTex);
    gl.uniform1i(this.u('m', 'uShadow'), 0);
    const aPos = gl.getAttribLocation(this.main!, 'aPos'), aNrm = gl.getAttribLocation(this.main!, 'aNrm');
    const nm = new Float32Array(9);
    for (const d of draws) {
      const g = this.upload(gl, d.mesh);
      gl.uniformMatrix4fv(this.u('m', 'uModel'), false, d.model);
      gl.uniformMatrix3fv(this.u('m', 'uNormal'), false, normalMatrix(d.model, nm));
      gl.uniform3fv(this.u('m', 'uColor'), d.colour);
      gl.bindBuffer(gl.ARRAY_BUFFER, g.pos); gl.enableVertexAttribArray(aPos); gl.vertexAttribPointer(aPos, 3, gl.FLOAT, false, 0, 0);
      gl.bindBuffer(gl.ARRAY_BUFFER, g.nrm); gl.enableVertexAttribArray(aNrm); gl.vertexAttribPointer(aNrm, 3, gl.FLOAT, false, 0, 0);
      gl.drawArrays(gl.TRIANGLES, 0, g.count);
    }
    gl.flush();
    target.drawImage(this.canvas, 0, 0);
  }

  private u(program: 'm' | 's', name: string): WebGLUniformLocation | null {
    const key = program + name;
    let loc = this.loc.get(key);
    if (loc === undefined) {
      loc = this.gl!.getUniformLocation(program === 'm' ? this.main! : this.shadow!, name);
      this.loc.set(key, loc);
    }
    return loc;
  }

  private upload(gl: WebGLRenderingContext, mesh: MeshHandle): GpuMesh {
    let g = this.uploaded.get(mesh);
    if (g) return g;
    const pos = gl.createBuffer()!, nrm = gl.createBuffer()!;
    gl.bindBuffer(gl.ARRAY_BUFFER, pos); gl.bufferData(gl.ARRAY_BUFFER, mesh.positions, gl.STATIC_DRAW);
    gl.bindBuffer(gl.ARRAY_BUFFER, nrm); gl.bufferData(gl.ARRAY_BUFFER, mesh.normals, gl.STATIC_DRAW);
    g = { pos, nrm, count: mesh.vertexCount };
    this.uploaded.set(mesh, g);
    return g;
  }

  /** The GL context, created on first use; null — with ONE console error — where WebGL is unavailable, in which
   *  case every flush draws nothing and the 2D layer is all there is. Degrading to "less picture" rather than to a
   *  thrown frame, because a thrown `on frame` stops the loop and takes the HUD with it. */
  private context(): WebGLRenderingContext | null {
    if (this.gl) return this.gl;
    if (this.failed) return null;
    const opts = { alpha: true, antialias: true, depth: true, premultipliedAlpha: true, preserveDrawingBuffer: false };
    const gl = (this.canvas.getContext('webgl2', opts) ?? this.canvas.getContext('webgl', opts)) as WebGLRenderingContext | null;
    if (!gl) {
      this.failed = true;
      console.error('[osy] Draw.Mesh needs WebGL and this browser offers none — the 3D layer is skipped; the 2D verbs still draw.');
      return null;
    }
    try {
      this.main = link(gl, MAIN_VS, MAIN_FS);
      this.shadow = link(gl, SHADOW_VS, SHADOW_FS);
      // The shadow map: an RGBA8 colour target with a depth renderbuffer. Nearest filtering — the PCF taps are
      // explicit, and a bilinear read of PACKED depth would blend bytes into nonsense.
      const tex = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, SHADOW_SIZE, SHADOW_SIZE, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      const depth = gl.createRenderbuffer();
      gl.bindRenderbuffer(gl.RENDERBUFFER, depth);
      gl.renderbufferStorage(gl.RENDERBUFFER, gl.DEPTH_COMPONENT16, SHADOW_SIZE, SHADOW_SIZE);
      const fbo = gl.createFramebuffer();
      gl.bindFramebuffer(gl.FRAMEBUFFER, fbo);
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
      gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.RENDERBUFFER, depth);
      if (gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE) { this.shadowFbo = fbo; this.shadowTex = tex; }
      else console.error('[osy] the shadow map could not be allocated on this GPU — meshes render without shadows.');
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      gl.enable(gl.DEPTH_TEST);
      gl.enable(gl.CULL_FACE);
      gl.cullFace(gl.BACK);
      gl.frontFace(gl.CCW);
    } catch (e) {
      this.failed = true;
      console.error('[osy] the 3D layer could not initialise —', e instanceof Error ? e.message : e);
      return null;
    }
    this.gl = gl;
    return gl;
  }
}

function link(gl: WebGLRenderingContext, vs: string, fs: string): WebGLProgram {
  const compile = (type: number, src: string): WebGLShader => {
    const sh = gl.createShader(type)!;
    gl.shaderSource(sh, src); gl.compileShader(sh);
    if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) throw new Error(`shader: ${gl.getShaderInfoLog(sh) ?? 'compile failed'}`);
    return sh;
  };
  const p = gl.createProgram()!;
  gl.attachShader(p, compile(gl.VERTEX_SHADER, vs));
  gl.attachShader(p, compile(gl.FRAGMENT_SHADER, fs));
  gl.linkProgram(p);
  if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(`program: ${gl.getProgramInfoLog(p) ?? 'link failed'}`);
  return p;
}
