import { renderLogTemplate, type OsyLogEntry } from './interpreter';

/** Where a client `Log.*` line goes. Slice 1 ships the CONSOLE sink; forwarding to the server (so the line lands in
 *  `osy logs` next to the server's, under the same correlation id) plugs in behind this same seam — the interpreter and
 *  the walker never learn which sinks exist. */
export interface OsyLogSink {
  write(entry: OsyLogEntry): void;
}

/** Map an Osy# level onto a console method. The six levels are Serilog's; the console has four, so Verbose and Debug
 *  both land on `console.debug` and Fatal joins Error — the LEVEL itself is still carried on the line (and on a
 *  forwarded one it is preserved exactly), so nothing is lost, it is only how the browser renders it. */
function consoleMethod(level: string): 'debug' | 'info' | 'warn' | 'error' {
  switch (level) {
    case 'Verbose':
    case 'Debug':
      return 'debug';
    case 'Warning':
      return 'warn';
    case 'Error':
    case 'Fatal':
      return 'error';
    default:
      return 'info';
  }
}

/** The console sink: a rendered, human-readable line, with the structured fields attached as a second argument so the
 *  browser shows them expandable rather than stringified into the text. Rendering happens HERE, for humans only — a
 *  forwarded line ships its template + fields and is rendered SERVER-side, so the stored message is identical to a
 *  server-written one. */
export class ConsoleLogSink implements OsyLogSink {
  write(entry: OsyLogEntry): void {
    const message = renderLogTemplate(entry.template, entry.fields);
    const method = consoleMethod(entry.level);
    const hasFields = Object.keys(entry.fields).length > 0;

    const parts: unknown[] = [`[osy] ${message}`];
    if (hasFields) parts.push(entry.fields);
    if (entry.exception !== undefined && entry.exception !== null) parts.push(entry.exception);

    console[method](...parts);
  }
}

/** Fan a line out to every sink. A sink that throws must NEVER break the app — logging is observability, and an
 *  observability call that can take down an action is worse than no logging at all. */
export class OsyLogger implements OsyLogSink {
  constructor(private readonly sinks: OsyLogSink[]) {}

  write(entry: OsyLogEntry): void {
    for (const sink of this.sinks) {
      try {
        sink.write(entry);
      } catch {
        // Deliberately swallowed: see above. Not even a console.error — a failing console sink would loop.
      }
    }
  }

  /** Drain every sink that buffers. Called when the page is going away: a batch still sitting in memory would
   *  otherwise die with the tab — and the lines you lose that way are the ones written just before the user left,
   *  which is usually exactly when it broke. */
  async flush(): Promise<void> {
    await Promise.all(this.sinks.map(async (s) => {
      const f = (s as { flush?: () => Promise<void> }).flush;
      if (typeof f === 'function') { try { await f.call(s); } catch { /* never surface a logging failure */ } }
    }));
  }
}

/** The six Serilog levels, quietest first — the order the floor compares against. */
const LEVELS = ['Verbose', 'Debug', 'Information', 'Warning', 'Error', 'Fatal'];

/** True when `level` is at or above `floor`. An unknown level is treated as Information rather than dropped: losing a
 *  line to a typo in its level would be a silly way to lose the record of what happened. */
export function meetsFloor(level: string, floor: string): boolean {
  const l = LEVELS.indexOf(level);
  const f = LEVELS.indexOf(floor);
  if (f < 0) return true;
  return (l < 0 ? LEVELS.indexOf('Information') : l) >= f;
}

/** What the forwarding sink posts. Note what is ABSENT: appId and userId. The server stamps those from the
 *  authenticated principal and ignores anything a client claims — see SECURITY-INVARIANT(client-log-ingress). Sending
 *  them would be pointless at best and a forgery attempt at worst. */
export interface ClientLogPayload {
  level: string;
  template: string;
  fields: Record<string, unknown>;
  exception?: string;
  correlationId?: string;
  source?: string;
  timestamp: string;
}

export interface ForwardOptions {
  /** POST a batch to the server. Rejecting is fine — the batch is dropped, never retried forever. */
  send(lines: ClientLogPayload[]): Promise<void>;
  /** Only forward at/above this level. Everything locally, Warning+ in cloud — the server re-checks it, because a
   *  client must never be trusted to limit itself. */
  floor?: string;
  /** How long to wait before flushing a partial batch. */
  flushMs?: number;
  /** The most lines to send in one request (the server caps this too). */
  maxBatch?: number;
  /** The most lines to hold in memory. Beyond this the OLDEST are dropped: an app that logs faster than the network
   *  drains must not grow a buffer without bound, and when you must lose something, the newest lines are the ones that
   *  explain what just went wrong. */
  maxBuffer?: number;
}

/** Forwards client log lines to the server, so they land in `osy logs` beside the server's — under the SAME
 *  correlation id, which is the entire reason this exists. Batched (a request per line would be absurd), bounded, and
 *  fire-and-forget: a logging failure must never surface to the app or be retried into a storm. */
export class ForwardingLogSink implements OsyLogSink {
  private readonly buffer: ClientLogPayload[] = [];
  private timer: ReturnType<typeof setTimeout> | undefined;
  private readonly floor: string;
  private readonly flushMs: number;
  private readonly maxBatch: number;
  private readonly maxBuffer: number;

  constructor(private readonly opts: ForwardOptions) {
    this.floor = opts.floor ?? 'Verbose';
    this.flushMs = opts.flushMs ?? 2000;
    this.maxBatch = opts.maxBatch ?? 64;
    this.maxBuffer = opts.maxBuffer ?? 500;
  }

  write(entry: OsyLogEntry): void {
    if (!meetsFloor(entry.level, this.floor)) return;   // below the floor: don't even buffer it

    this.buffer.push({
      level: entry.level,
      template: entry.template,
      fields: entry.fields,
      exception: entry.exception === undefined || entry.exception === null
        ? undefined
        : stringifyException(entry.exception),
      correlationId: entry.correlationId,
      source: entry.source,
      timestamp: new Date().toISOString(),
    });

    // Drop the OLDEST on overflow — see maxBuffer.
    while (this.buffer.length > this.maxBuffer) this.buffer.shift();

    if (this.buffer.length >= this.maxBatch) void this.flush();
    else this.schedule();
  }

  private schedule(): void {
    if (this.timer !== undefined) return;
    this.timer = setTimeout(() => { this.timer = undefined; void this.flush(); }, this.flushMs);
  }

  /** Send what we have. Safe to call at any time (including on page hide). */
  async flush(): Promise<void> {
    if (this.timer !== undefined) { clearTimeout(this.timer); this.timer = undefined; }
    if (this.buffer.length === 0) return;

    const batch = this.buffer.splice(0, this.maxBatch);
    try {
      await this.opts.send(batch);
    } catch {
      // Dropped. NOT re-queued: a server that is down or rejecting would otherwise grow an unbounded backlog and
      // hammer it — a logging subsystem that amplifies an outage is worse than one that loses lines during it.
    }
    if (this.buffer.length > 0) this.schedule();
  }
}

/** A browser error is usually an Error; it can be anything. Keep the stack when there is one — it is the whole value of
 *  the line — and never throw while trying to describe a throw. */
function stringifyException(e: unknown): string {
  try {
    if (e instanceof Error) return e.stack ?? `${e.name}: ${e.message}`;
    if (typeof e === 'string') return e;
    return JSON.stringify(e) ?? String(e);
  } catch {
    return String(e);
  }
}

/** The default client logger: console only (no session to forward through — a static preview, a bare mount). */
export function defaultLogger(): OsyLogger {
  return new OsyLogger([new ConsoleLogSink()]);
}

/** A sink that RETAINS the last N lines so they can be read back (`__osy.logs`, the inspector's Logs tab).
 *
 *  The forwarding sink already buffers, but that buffer is a DRAIN — `flush()` splices lines out on their way to the
 *  server, so by the time you want to look, they are gone. This keeps its own bounded copy. It is the use the sink
 *  seam was written for ("a sink (console, the dev inspector, …)"). */
export class RingLogSink implements OsyLogSink {
  private readonly lines: OsyLogEntry[] = [];
  constructor(private readonly max = 200) {}
  write(entry: OsyLogEntry): void {
    this.lines.push(entry);
    if (this.lines.length > this.max) this.lines.shift();
  }
  all(): readonly OsyLogEntry[] { return this.lines; }
  clear(): void { this.lines.length = 0; }
}

/** The production logger: the console (instant, no round-trip) AND the server (so the line lands in `osy logs`). */
export function forwardingLogger(opts: ForwardOptions): OsyLogger {
  return new OsyLogger([new ConsoleLogSink(), new ForwardingLogSink(opts)]);
}

/** The dev-host logger: the production pair PLUS a readable ring. Only the local dev server builds this one. */
export function forwardingLoggerWithRing(opts: ForwardOptions, ring: RingLogSink): OsyLogger {
  return new OsyLogger([new ConsoleLogSink(), new ForwardingLogSink(opts), ring]);
}

/** The minimal slice of `window` this needs — so it is testable without a browser. */
export interface ErrorCaptureTarget {
  addEventListener(type: string, listener: (event: unknown) => void): void;
  removeEventListener?(type: string, listener: (event: unknown) => void): void;
}

/**
 * Capture the errors that escape everything else, and log them.
 *
 * A failing Osy# ACTION is already logged where it happens (the walker knows the interaction's correlation id there,
 * which is worth far more than a generic handler could reconstruct). But until now anything thrown OUTSIDE an action —
 * a stray promise rejection, an error in a render callback or a foreign control — went to the browser console and
 * NOWHERE else: `osy-client` had no `window.onerror` and no `unhandledrejection` handler at all. Those are precisely
 * the failures nobody is watching for, on a user's machine you cannot reach.
 *
 * They are logged at `Error` with no correlation id, because honestly there isn't one — they did not happen inside a
 * known interaction, and inventing an id would fabricate a trace that never existed.
 *
 * Returns a disposer. Never rethrows, never calls `preventDefault`: capturing an error must not change what the page
 * does with it.
 */
// The browser's benign ResizeObserver notices. These are NOT app faults: the spec dispatches a window `error` event
// when an observer callback caused layout the browser deferred to the next frame — it recovers on its own, carries NO
// `error` object and no source location, and every app with a ResizeObserver eventually emits them (ours is the grid's
// responsive container-query relayout, X25). Logging them at `Error` reads as a real fault in `osy logs`. We skip
// EXACTLY these two known strings, and only when there is no real `error` object — so a genuine thrown error is never
// swallowed; this is a targeted filter, not a blanket silence.
const BENIGN_RESIZE_OBSERVER_MESSAGES: ReadonlySet<string> = new Set([
  'ResizeObserver loop completed with undelivered notifications.',
  'ResizeObserver loop limit exceeded',
]);

export function captureGlobalErrors(logger: OsyLogSink, target: ErrorCaptureTarget): () => void {
  const onError = (event: unknown) => {
    const e = event as { error?: unknown; message?: string; filename?: string; lineno?: number };
    // The benign ResizeObserver notice (no `error` object) is browser noise, not an app fault — do not log it.
    if (!e?.error && typeof e?.message === 'string' && BENIGN_RESIZE_OBSERVER_MESSAGES.has(e.message)) return;
    logger.write({
      level: 'Error',
      template: 'Uncaught error: {Message}',
      fields: {
        Message: e?.message ?? 'unknown',
        // Where it came from, when the browser tells us — a stack alone is often minified to uselessness.
        Location: e?.filename ? `${e.filename}:${e.lineno ?? 0}` : undefined,
      },
      exception: e?.error ?? e?.message,
      source: 'window.onerror',
    });
  };

  const onRejection = (event: unknown) => {
    const e = event as { reason?: unknown };
    logger.write({
      level: 'Error',
      template: 'Unhandled promise rejection',
      fields: {},
      exception: e?.reason,
      source: 'unhandledrejection',
    });
  };

  target.addEventListener('error', onError);
  target.addEventListener('unhandledrejection', onRejection);

  return () => {
    target.removeEventListener?.('error', onError);
    target.removeEventListener?.('unhandledrejection', onRejection);
  };
}
