// The ONE place a declared field default becomes a runtime value.
//
// Two callers, and they used to be one: a `class` object-initializer applies the defaults the server pre-resolved onto
// the instance it is building (`applyFieldDefaults`), and an ENTITY ghost (`new Plant { … }` in a client action) seeds
// the same shape onto the optimistic row the overlay materializes (`UnitOfWork.create`). The `now` token has to be
// evaluated PER CONSTRUCTION against the client clock — a frozen value could not represent "the instant this row was
// made" — so the rule cannot live at the projection and has to live here, where both reach it.

import { Dec } from './decimal.js';
import { OsyDateTime, OsyDateOnly, OsyTimeOnly } from './datetime.js';
import type { FieldDefault } from './tree.js';

/** One declared default's runtime value. A `now` token reads the CLIENT clock at this call; a `dec` default carries
 *  the exact base-10 digit string and parses exactly as an inline decimal literal does (representation parity);
 *  everything else is already the value. */
export function materialiseFieldDefault(d: FieldDefault): unknown {
  if (d.now !== undefined) return temporalDefault(d.now);
  return d.dec === true ? Dec.parse(String(d.value)) : d.value;
}

/** A `= DateTime.Now` / `DateOnly.Today` / `TimeOnly.Now` field default, evaluated against the CLIENT clock at
 *  construction (the same UTC instant source as `Clock.Now`, so the value matches the server's for a pinned clock). */
export function temporalDefault(kind: 'now' | 'today' | 'timenow'): unknown {
  const now = OsyDateTime.utcNow();
  switch (kind) {
    case 'now': return now;
    case 'today': return OsyDateOnly.fromDateTime(now);
    case 'timenow': return OsyTimeOnly.fromDateTime(now);
  }
}
